/* SmartVio Studio V12 — original interface and workflow controller. */
'use strict';
(() => {
  const browserLang=/^ja/i.test(navigator.language)?'ja':/^de/i.test(navigator.language)?'de':/^zh/i.test(navigator.language)?'zh':'en';
  const browserRegion={ja:'jp',de:'de',zh:'cn',en:/^en-GB/i.test(navigator.language)?'uk':'us'}[browserLang];
  const defaults={song:'S001',lang:browserLang,region:browserRegion,theme:'light',appMode:new URLSearchParams(location.search).get('mode')==='offline'?'offline':'full',tutorialAuto:true,preset:'Acoustic',effects:{volume:.75,reverb:.18,delay:0,compression:.2},bpm:80,a4:440,semitone:0,meter:'4/4',from:1,to:0,repeat:false,barCount:4,favorites:[],levels:[.7,.7,.7,.7],mutes:[false,false,false,false],source:'synth',string:'A4',inputGain:1,alignLoops:false};
  let stored={};try{stored=JSON.parse(localStorage.getItem('sv12-prefs')||'{}')||{};}catch{}
  const prefs={...defaults,...stored,effects:{...defaults.effects,...stored.effects}};
  // Defaults and repaired preferences never count as an explicit first-run choice.
  let localeChoiceConfirmed=stored.localeChoiceVersion===1&&['us','uk','jp','de','cn','fr'].includes(stored.region)&&['zh','en','ja','de'].includes(stored.lang);
  if(!localeChoiceConfirmed)prefs.localeChoiceVersion=0;
  for(const key of ['favorites','levels','mutes'])if(!Array.isArray(prefs[key]))prefs[key]=defaults[key].slice();
  if(!['zh','en','ja','de'].includes(prefs.lang))prefs.lang=browserLang;
  if(!['us','uk','jp','de','cn','fr'].includes(prefs.region))prefs.region='cn';
  if(!['full','offline'].includes(prefs.appMode))prefs.appMode='full';
  if(!['all','regional','global'].includes(prefs.libraryScope))prefs.libraryScope='all';
  prefs.tutorialAuto=prefs.tutorialAuto!==false;
  if(!SVAudioEngine.presets.includes(prefs.preset))prefs.preset='Acoustic';
  if(typeof prefs.inputGain!=='number'||!Number.isFinite(prefs.inputGain)||prefs.inputGain<0||prefs.inputGain>2)prefs.inputGain=1;
  prefs.alignLoops=prefs.alignLoops===true;
  const nav=[['home','我的琴房','My studio','Meine Musik','マイスタジオ','Mon studio','house','MY WORKSPACE'],['library','曲库','Library','Bibliothek','曲ライブラリ','Bibliothèque','library','FIND YOUR NEXT MELODY'],['practice','练习','Practice','Üben','練習','Pratique','music-2','ONE PHRASE AT A TIME'],['studio','录音创作','Create','Aufnehmen','録音・創作','Créer','audio-lines','CAPTURE YOUR SOUND'],['tones','音色工作台','Sounds','Klänge','音色','Sons','sliders-horizontal','SHAPE YOUR SOUND'],['tuner','调音器','Chromatic tuner','Stimmgerät','チューナー','Accordeur','activity','TUNE YOUR STRINGS'],['metronome','节拍器','Metronome','Metronom','メトロノーム','Métronome','timer','KEEP YOUR TIME'],['device','我的设备','Devices','Geräte','デバイス','Appareils','bluetooth','YOUR INSTRUMENT'],['learn','学习路径','Learn','Lernen','学習','Apprendre','graduation-cap','BUILD YOUR CONFIDENCE'],['community','社区','Community','Community','コミュニティ','Communauté','users','PLAY. SHARE. CONNECT.'],['shop','产品探索','Explore','Entdecken','製品','Explorer','shopping-bag','SMARTVIO COLLECTION'],['profile','我的设置','Settings','Einstellungen','設定','Réglages','settings-2','MAKE IT YOURS']];
  nav.splice(4,0,['performance','伴奏与弦乐','Backing & strings','Begleitung','伴奏と弦楽','Accompagnement','music-4','ORIGINAL MUSIC'],['midi','MIDI 工作台','MIDI studio','MIDI-Studio','MIDIスタジオ','Studio MIDI','piano','COMPOSE & EDIT']);
  const languages={zh:1,en:2,de:3,ja:4,fr:5},catNames={beginner:'入门练习',classic:'经典旋律',folk:'民谣小品',custom:'自建练习'};
  const toneNames={Acoustic:['原声素描','audio-lines','清晰 · 基础练习'],Warm:['暖木色','sun','柔和 · 慢板'],Bright:['明亮弦声','sparkles','清亮 · 旋律'],Electric:['电音线条','zap','锐利 · 流行'],Bass:['低音空间','waves','厚实 · 低音'],Piano:['琴键瞬间','piano','短音 · 轻巧'],Organ:['复古风琴','radio','持续 · 复古'],Strings:['弦乐铺陈','music-4','绵长 · 合奏'],Pad:['氛围云层','cloud','缓起 · 空间']};
  const courses=[{id:'begin',title:'从第一根空弦开始',label:'起步 · 3 个步骤',icon:'sprout',lessons:[['hold','持琴与放松','轻放左手，找到舒适的肩颈位置。先在镜前检查姿势，不急着加快。'],['open','认识 G / D / A / E 空弦','用调音器确认四根弦。每根弦慢拉四拍，听稳定的长音。'],['bow','平稳运弓','在弓的中段开始。手腕放松，让四拍长音保持均匀。']]},{id:'melody',title:'把旋律拉得更连贯',label:'进阶 · 3 个步骤',icon:'music-2',lessons:[['finger','第一把位音准','先听参考音，再慢拉。用 A–B 段落反复练习困难的两个小节。'],['cross','换弦与节奏','节拍器从 60 BPM 开始，先空弦换弦，再加入左手。'],['phrase','完整乐句','先示范聆听，再跟奏。连续演奏一个乐句后休息并复盘。']]},{id:'create',title:'留下属于你的声音',label:'创作 · 3 个步骤',icon:'mic',lessons:[['tone','选择合适的音色','试听基础音色，少量添加混响。当前音色作用于浏览器示范。'],['record','录下第一段旋律','在录音页选择真实麦克风，录下慢速乐句。停止后回听并下载备份。'],['layer','尝试四轨循环','先录简单长音，再加入旋律。每轨按自己的录制长度循环。']]}];
  let page='home',category='all',query='',listView=prefs.libraryView==='grid'?false:prefs.libraryView==='list'?true:matchMedia('(max-width:760px)').matches,media=[],urls=new Map(),waveCache=new Map(),run=null,runId=0,capture=null,capturePending=false,captureGeneration=0,saving=false,tuner=false,metro=false,chord=null,loopsPlaying=false,loopRequest=0,recordTimer=null,navigationId=0,midiPorts=[],searchTimer;
  const engine=SVAudioEngine;
  const learningPath=SVLearningPath.createPath({environment:window});
  const persist=()=>{try{localStorage.setItem('sv12-prefs',JSON.stringify(prefs));return true;}catch{notify('设置暂存于内存；浏览器未允许保存。');return false;}};
  const T=value=>window.SVLocale?.text(String(value??''),prefs.lang,prefs.region)??String(value??'');
  const brandFor=(lang,region)=>window.SVLocale?.brand(lang,region)||(region==='uk'||lang==='de'?'VELLEN':'Silvio');
  const brand=()=>brandFor(prefs.lang,prefs.region);
  function brandMarkup(name){
    const logos={Silvio:{file:'silvio-wordmark.png',className:'silvio',width:1915,height:821},VELLEN:{file:'vellen-wordmark.png',className:'vellen',width:2135,height:736}},logo=name==='Silvio'||name==='VELLEN'?logos[name]:null;
    return logo?`<span class="brand-wordmark brand-wordmark-${logo.className}" role="img" aria-label="${E(name)}" data-brand-wordmark="${E(name)}" data-i18n-ignore><img src="brands/${logo.file}" alt="${E(name)}" width="${logo.width}" height="${logo.height}" decoding="async" draggable="false"><span class="brand-wordmark-fallback" aria-hidden="true">${E(name)}</span></span>`:`<span class="brand-text" data-i18n-ignore>${E(name)}</span>`;
  }
  document.addEventListener('error',event=>{if(event.target?.matches?.('.brand-wordmark img'))event.target.parentElement.classList.add('is-failed');},true);
  const marketLanguages={us:'en',uk:'en',jp:'ja',de:'de',cn:'zh',fr:'en'};
  const localeTag=()=>({zh:'zh-CN',ja:'ja-JP',de:'de-DE',en:prefs.region==='uk'?'en-GB':'en-US'})[prefs.lang];
  const title=s=>s?.category==='custom'?(s.title||''):(s?.titles?.[prefs.lang]||T(s?.titles?.zh||s?.title||''));
  const sessionTitle=row=>{const selected=svState.songs.find(s=>s.id===row.songId);return selected?title(selected):T(row.song);};
  let lockedOverflow=null,countryDraft=prefs.region,languageDraft=prefs.lang,startupTimer=null,practiceSettingsOpen=matchMedia('(min-width:761px)').matches;
  window.SVLocale?.setLanguage(prefs.lang,prefs.region);
  const song=()=>svState.songs.find(s=>s.id===prefs.song)||svState.songs[0];
  let cloudCleanup=null;
  const midiStudio=SVMIDI.createStudio({notify,play:async doc=>{await finishPractice();return engine.play(SVMIDI.toPlan(doc,prefs.a4));}});
  const performanceStudio=SVPerformance.createStudio({store:SVMediaStore,engine,notify,getPreferences:()=>prefs,stopOtherAudio:()=>engine.stop(),playScale:async scale=>{engine.stop();const beat=60/prefs.bpm;return engine.play(scale.notes.map((pitch,i)=>({i,start:i*beat,end:(i+1)*beat,freq:SVScoreModel.frequency(pitch,prefs.a4)})));},practiseScale:openScale});
  const videoManager=SVVideoCapture.createVideoCapture({onStatus:state=>{if(capture?.kind==='video'&&!state.recording&&!state.pending&&!saving)queueMicrotask(()=>{if(capture?.kind==='video'&&!saving)stopRecord().catch(e=>notify(e.message));});}});
  let deviceBridge=null,lastBleErrorAt=0,bleDecodeState=null;
  deviceBridge=SVDeviceBridge.createDeviceBridge({environment:window,provider:window.SVInstrumentAdapter,onState:state=>{updateDeviceStatus();if(state.ble?.connected===false){bleDecodeState=null;midiStudio.stopExternalCapture?.('disconnected');}},onMidiPacket:packet=>{if(packet.transport!=='ble-midi')return;try{const decoded=SVDeviceBridge.decodeBleMidiPacket(packet.bytes,bleDecodeState);bleDecodeState=decoded.state;for(const event of decoded.events)midiStudio.ingestExternalMessage?.(event.data,packet.receivedAt);}catch(error){bleDecodeState=null;midiStudio.stopExternalCapture?.('parse-error');if(performance.now()-lastBleErrorAt>5000){lastBleErrorAt=performance.now();notify(error.message);}}}});
  function updateDeviceStatus(){if(!deviceBridge)return;const state=deviceBridge.status(),el=$('#device-bridge-state'),audio=engine.status();const header=$('.device-status span');if(header){header.setAttribute('data-i18n-ignore','');header.textContent=T(state.ble.connected?'蓝牙 MIDI 已连接':state.native.connected?'琴端参数适配器已连接':'设备未连接');}if(el)el.textContent=T(state.ble.connected?'蓝牙 MIDI 已连接':'蓝牙 MIDI 未连接')+'\n'+T(state.native.connected?'琴端参数适配器已连接':'琴端参数待型号适配')+'\n'+T('琴端到输出设备的时延尚未实测。')+(audio.baseLatency!==null?'\n'+T('浏览器音频缓冲估计')+' '+Math.round(audio.baseLatency*1000)+' ms':'');for(const el of document.querySelectorAll('[data-action="capture-ble-midi"]'))el.disabled=!state.ble.connected;for(const el of document.querySelectorAll('[data-action="store-preset-device"]'))el.disabled=!state.native.connected;}
  async function restorePresets(records){const ok=await action({type:'presets-import',presets:records});if(ok)render();return !!ok;}
  async function openScale(scale){const melody=scale.notes.map(note=>note+':1').concat([...scale.notes].reverse().map(note=>note+':1')).join(' ');let exercise=svState.songs.find(s=>s.category==='custom'&&s.author==='Original first-position exercise'&&s.melody===melody);if(!exercise){const value={id:'EXERCISE_'+scale.id+'_'+crypto.randomUUID().replaceAll('-','').slice(0,8),title:scale.name+' scale',author:'Original first-position exercise',category:'custom',melody};if(!await action({type:'personal-song',song:value}))return;exercise=svState.songs.find(s=>s.id===value.id);}prefs.song=exercise.id;prefs.meter='4/4';prefs.from=1;prefs.to=0;persist();location.hash='practice';}
  function performanceView(){return '<div id="performance-host" data-i18n-ignore></div>';}
  function midiView(){return pageHeading('MIDI 工作台','接收真实音符，编辑旋律，导出标准 MIDI 文件。')+'<div class="button-row">'+button('连接蓝牙 MIDI','connect-ble-midi','bluetooth','secondary')+button('收录蓝牙 MIDI','capture-ble-midi','circle','secondary')+button('停止 MIDI 收录','stop-ble-midi','square','secondary')+'</div><div id="midi-host" data-i18n-ignore></div>';}
  function presetExtras(){return '<section class="panel"><h3>'+E(T('麦克风输入增益'))+'</h3><p>'+E(T('只调节本机麦克风录音，不改变琴内拾音器硬件灵敏度。'))+'</p><label><span id="input-gain-value">'+Math.round(prefs.inputGain*100)+'%</span><input type="range" min="0" max="200" value="'+Math.round(prefs.inputGain*100)+'" data-pref="inputGain" aria-label="'+E(T('麦克风输入增益'))+'"></label><label class="button secondary preset-import-label">'+E(T('导入预设'))+'<input type="file" id="preset-import" accept="application/json,.json"></label></section><div id="preset-cloud" data-i18n-ignore></div>';}
  function bridgeControls(){const caps=SVDeviceBridge.detectCapabilities(window);return '<section class="panel"><h3>'+E(T('蓝牙 MIDI 与琴端参数'))+'</h3><p>'+E(T(caps.webBluetooth?'当前浏览器支持蓝牙 MIDI 配对。':'当前浏览器不支持网页蓝牙，请使用系统 MIDI 或原生适配器。'))+'</p><div class="button-row">'+button('连接蓝牙 MIDI','connect-ble-midi','bluetooth','primary')+button('断开设备','disconnect-bridge','square','secondary')+goButton('MIDI 工作台','midi','piano','secondary')+(window.SVInstrumentAdapter?button('连接琴端参数','connect-native','sliders-horizontal','secondary'):'')+button('将当前预设保存至琴','store-preset-device','save','secondary')+'</div><pre id="device-bridge-state" class="device-state"></pre><p>'+E(T('蓝牙 MIDI 传送音符事件，不是实时演奏音频。低延迟监听建议使用琴的有线耳机或音频输出。'))+'</p><p>'+E(T('写入琴内存储需要型号适配器和设备确认；无适配器不会发送参数。'))+'</p></section>';}

  const nameOf=id=>nav.find(n=>n[0]===id)?.[languages[prefs.lang]]||id;
  const button=(label,act,ic='arrow-right',cls='secondary',extra='')=>`<button class="button ${cls}" data-action="${act}" ${extra}>${icon(ic)}<span>${E(label)}</span></button>`;
  const goButton=(label,id,ic='arrow-right',cls='secondary')=>`<button class="button ${cls}" data-go="${id}">${icon(ic)}<span>${E(label)}</span></button>`;
  const date=at=>new Date(at).toLocaleDateString(localeTag(),{month:'short',day:'numeric'});
  const seconds=n=>`${Math.floor(Math.max(0,n)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,n)%60).toString().padStart(2,'0')}`;
  const empty=(heading,copy,ic='music-2')=>`<div class="empty-state">${icon(ic)}<strong>${E(heading)}</strong><p>${E(copy)}</p></div>`;
  const pageHeading=(heading,copy,right='')=>`<div class="page-heading"><div><h2>${E(heading)}</h2><p>${E(copy)}</p></div>${right}</div>`;
  const today=at=>new Date(at).toDateString()===new Date().toDateString();
  const rangeModel=()=>{const [numerator,denominator]=prefs.meter.split('/').map(Number);const score=SVScoreModel.createScore(song(),{numerator,denominator});score.barCount=Math.ceil(score.totalTicks/score.ticksPerBar);prefs.from=Math.min(score.barCount,Math.max(1,Math.round(Number(prefs.from)||1)));prefs.to=Math.min(score.barCount,Math.max(0,Math.round(Number(prefs.to)||0)));if(prefs.to&&prefs.to<prefs.from)prefs.to=prefs.from;const range=SVScoreModel.selectBars(score,prefs.from,prefs.to);return {score,range,plan:SVScoreModel.plan(range,prefs.bpm,prefs.a4,prefs.semitone)};};
  const kindName=row=>row.inputRoute==='microphone'||row.kind==='mic-scored'?'麦克风跟奏':'示范聆听';
  const sceneColors=['#ead9bb','#d6e4dd','#dfdbef','#edd3cd','#cfdde9','#ece1c6'];
  // Artwork is bound to a catalog ID, so searching, filtering and language changes keep the same cover.
  const songArtwork=Object.freeze(Object.fromEntries(Array.from({length:35},(_,i)=>{const id='S'+String(i+1).padStart(3,'0');return [id,'covers/'+id.toLowerCase()+'.jpg'];})));
  function songImage(s){const coverId=Object.hasOwn(songArtwork,s.coverId)?s.coverId:s.id,src=Object.hasOwn(songArtwork,coverId)?songArtwork[coverId]:null;return src?`<img class="song-cover-image" data-song-cover="${E(s.id)}" src="${src}" width="512" height="512" alt="" loading="lazy" decoding="async" draggable="false">`:'';}
  function sourceURL(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch{return null;}}
  const isExcerpt=s=>s?.practice?.kind==='excerpt';
  const verifiedSource=s=>s?.rights?.status==='verified-source'&&Boolean(sourceURL(s?.source?.url));
  function songBadges(s){return `${isExcerpt(s)?`<span class="badge">${E(T('练习短版'))}</span>`:''}<span class="badge ${verifiedSource(s)?'source-verified':'pending'}">${E(T(verifiedSource(s)?'来源已核对':s.category==='custom'?'自建练习':'候选谱本'))}</span>`;}
  function sourceButton(s){return sourceURL(s?.source?.url)?button('来源','song-source','book-open','secondary small song-source-button',`data-id="${E(s.id)}" aria-label="${E(T('查看曲目来源'))} ${E(title(s))}"`):'';}
  function practiceMeter(s){const value=s?.practice?.meter,match=typeof value==='string'?/^(\d{1,2})\/(2|4|8|16)$/.exec(value):null;return match&&Number(match[1])>=1&&Number(match[1])<=12?`${Number(match[1])}/${Number(match[2])}`:'4/4';}
  function meterOptions(){return [...new Set(['2/4','3/4','4/4','6/8',prefs.meter])].filter(value=>/^(?:[1-9]|1[0-2])\/(?:2|4|8|16)$/.test(value));}
  function sourceDialog(s){
    const source=s.source||{},link=(label,value)=>{const url=sourceURL(value);return url?`<a class="song-source-link" href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(T(label))}${icon('external-link')}</a>`:'';};
    const fields=[['原谱版本',source.edition],['原谱乐器',s.practice?.originalInstrument],['许可标注',source.license],['署名',source.attribution]].filter(([,value])=>typeof value==='string'&&value.trim());
    const label=s.practice?.label,excerptLabel=typeof label==='string'?label:label&&typeof label==='object'?label[prefs.lang]||label.en||label.zh:'';
    modal(`<section class="song-source-dialog"><h2 data-i18n-ignore>${E(title(s))}</h2><div class="song-source-badges">${songBadges(s)}</div>${excerptLabel?`<p data-i18n-ignore>${E(excerptLabel)}</p>`:''}<p>${E(T('练习短版仅节选旋律；来源核对不等于全球发行授权。'))}</p><dl>${fields.map(([heading,value])=>`<div><dt>${E(T(heading))}</dt><dd data-i18n-ignore>${E(value)}</dd></div>`).join('')}</dl><div class="song-source-links">${link('查看公开谱本',source.url)}${link('查看许可说明',source.licenseUrl)}</div><p class="help-text">${E(T('谱面与示范为练习用节选，不代表完整原作录音。'))}</p></section>`);
  }
  function songCard(s,i=0){const fav=prefs.favorites.includes(s.id),image=songImage(s);return `<article class="song-card${image?' has-artwork':''}"><div class="song-cover" style="--cover:${sceneColors[i%6]}">${image||`<span class="cover-number">${String(i+1).padStart(2,'0')}</span>${icon('music-2')}`}<button class="favorite ${fav?'active':''}" data-action="favorite" data-id="${E(s.id)}" data-i18n-ignore aria-label="${E(T(fav?'取消收藏':'收藏'))} ${E(title(s))}" aria-pressed="${fav}">${icon('heart')}</button></div><button class="song-title" data-i18n-ignore data-action="choose-song" data-id="${E(s.id)}">${E(title(s))}</button><div class="song-meta">${E(T(catNames[s.category]||'旋律'))} · <span data-i18n-ignore>${E(s.category==='custom'?s.author:T(s.author))}</span></div><div class="song-bottom"><div class="song-evidence">${songBadges(s)}${sourceButton(s)}</div><button class="icon-button" data-action="choose-song" data-id="${E(s.id)}" data-i18n-ignore aria-label="${E(T('练习'))} ${E(title(s))}">${icon('arrow-up-right')}</button></div></article>`;}
  let offlinePreparing=false;
  const modeName=()=>prefs.appMode==='offline'?'离线免注册':'当前模式';
  function offlineState(){return window.SVOffline?.status()||{ready:false,supported:false};}
  function offlineStatusText(){const state=offlineState();return offlinePreparing?'正在下载离线资源…':!state.supported?'此浏览器暂不支持离线缓存。':state.ready?'离线资源已就绪':'离线资源尚未就绪';}
  function modePanel(){return `<section class="panel mode-panel"><div class="panel-header"><div><span class="eyebrow">YOUR WAY TO PLAY</span><h3>使用模式</h3></div>${icon(prefs.appMode==='offline'?'wifi-off':'layout-grid')}</div><div class="mode-options" role="group" aria-label="使用模式">${[['full','当前模式','保留当前完整功能，社区发布需要联网登录。','layout-grid'],['offline','离线免注册','无需注册。下载离线资源后，可断网使用调音、练习和录音。','wifi-off']].map(([id,h,copy,ic])=>`<button type="button" class="mode-option ${prefs.appMode===id?'selected':''}" data-action="set-mode" data-mode="${id}" aria-pressed="${prefs.appMode===id}">${icon(ic)}<span><strong>${E(h)}</strong><small>${E(copy)}</small></span>${prefs.appMode===id?icon('circle-check'):''}</button>`).join('')}</div><div class="offline-status-line"><span class="badge ${offlineState().ready?'':'pending'}" id="offline-status" role="status">${E(T(offlineStatusText()))}</span>${button(offlineState().ready?'重新准备离线资源':'准备离线资源','prepare-offline','download','secondary small',offlinePreparing?'disabled':'')}</div><p class="help-text">首次下载需要联网；录音和麦克风仍需要浏览器授权。</p><p class="help-text">当前模式与离线模式共用本机记录，切换不会清空。</p></section><section class="panel guide-settings"><div class="panel-header"><h3>图文使用教学</h3>${icon('book-open')}</div><p>设置图文引导与使用模式。</p>${button('重新查看教学','tutorial','book-open','secondary')}<label class="guide-auto-setting"><input type="checkbox" data-pref="tutorialAuto" ${prefs.tutorialAuto?'checked':''}><span>下次进入显示教学</span></label></section>`;}
  async function prepareOffline(force=false){
    if(offlinePreparing)return;offlinePreparing=true;updateOfflineUI();
    try{const result=await window.SVOffline?.prepare({force});if(!result?.ready)notify('离线缓存准备失败，请联网后重试。');else notify('离线资源已就绪');}
    finally{offlinePreparing=false;updateOfflineUI();}
  }
  function updateOfflineUI(){
    const state=offlineState();document.querySelectorAll('#offline-status,[data-offline-status]').forEach(el=>{el.textContent=T(offlineStatusText());if(el.classList.contains('badge'))el.classList.toggle('pending',!state.ready);});

    document.querySelectorAll('[data-action="prepare-offline"]').forEach(el=>{el.disabled=offlinePreparing;const label=el.querySelector('span');if(label)label.textContent=T(state.ready?'重新准备离线资源':'准备离线资源');});
  }
  let guideCloud=null,guideCloudStatus='idle',guideSyncRunning=false,guideRetryTimer=null,guideRetryAttempts=0,guideSaveSequence=0,guideSyncNotice=null,audioPending=0;
  const guideOpened=new Set(),guideAcknowledged=new Map();
  function guideActor(){return prefs.appMode==='full'?window.SVCommunity?.viewer()?.id||'guest':'offline';}
  const guideStorageKey=actor=>'sv12-beginner-v2:'+encodeURIComponent(actor);
  function readGuideLocal(actor){let local=null;try{local=JSON.parse(localStorage.getItem(guideStorageKey(actor))||'null');}catch{}return local?.guideVersion===2&&Number.isInteger(local.step)&&local.step>=0&&local.step<=6&&['legacy','pending','in_progress','completed','skipped'].includes(local.status)?local:null;}
  function guideProgress(){
    const local=readGuideLocal(guideActor());
    const cloud=prefs.appMode==='full'?guideCloud:null;
    if(local?.dirty&&guideAcknowledged.get(guideActor())?.clientSaveId===local.clientSaveId)return guideAcknowledged.get(guideActor()).progress;
    if(local?.dirty)return local;
    if(cloud?.guideVersion===2&&(!local||Date.parse(cloud.updatedAt||'')>Date.parse(local.updatedAt||'')))return cloud;
    return local||cloud||{guideVersion:2,step:0,status:'pending'};
  }
  function scheduleGuideSync(){clearTimeout(guideRetryTimer);guideRetryTimer=setTimeout(async()=>{guideRetryTimer=null;const actor=guideActor();if(navigator.onLine&&actor!=='guest'&&actor!=='offline'&&readGuideLocal(actor)?.dirty&&['error','idle'].includes(guideCloudStatus))await window.SVCommunity?.connect(communityContext())?.catch(()=>{});void flushGuideProgress();},Math.min(30000,1500*2**Math.min(guideRetryAttempts++,5)));}
  async function flushGuideProgress(){
    const actor=guideActor(),value=readGuideLocal(actor);
    if(guideSyncRunning||actor==='guest'||actor==='offline'||!value?.dirty||guideAcknowledged.get(actor)?.clientSaveId===value.clientSaveId||!navigator.onLine)return;
    if(guideCloudStatus!=='ready'){scheduleGuideSync();return;}
    guideSyncRunning=true;clearTimeout(guideRetryTimer);guideRetryTimer=null;let acknowledged=false;
    try{
      const response=await window.SVCommunity.saveOnboarding(value,actor),ack=response.result;
      if(!ack||ack.guideVersion!==2)throw Error('Missing onboarding acknowledgement');
      guideAcknowledged.set(actor,{clientSaveId:value.clientSaveId,progress:ack});guideRetryAttempts=0;guideSyncNotice=null;acknowledged=true;
      const current=readGuideLocal(actor);
      if(current?.clientSaveId===value.clientSaveId)try{localStorage.setItem(guideStorageKey(actor),JSON.stringify({...ack,dirty:false}));}catch{notify(prefs.lang==='zh'?'账号进度已同步，本机缓存暂未更新。':({en:'Account progress is synced; the local cache could not update.',ja:'アカウントと同期済みですが、端末のキャッシュを更新できませんでした。',de:'Der Kontofortschritt ist synchronisiert; der lokale Cache konnte nicht aktualisiert werden.'})[prefs.lang]);}
    }catch(error){if(error.code!=='BUSY'&&guideSyncNotice!==actor){guideSyncNotice=actor;notify(prefs.lang==='zh'?'账号进度暂未同步，已保留在本机；恢复连接后会自动补传。':({en:'Progress stays on this device and will sync when the connection returns.',ja:'進捗は端末に保存されています。接続が戻ると自動で同期します。',de:'Der Fortschritt bleibt auf diesem Gerät und wird bei wiederhergestellter Verbindung synchronisiert.'})[prefs.lang]);}}
    finally{guideSyncRunning=false;}
    const latest=readGuideLocal(actor);
    if(guideActor()===actor&&latest?.dirty&&guideAcknowledged.get(actor)?.clientSaveId!==latest.clientSaveId){if(acknowledged)void flushGuideProgress();else scheduleGuideSync();}
    else if(page==='learn'&&!window.SVTutorial?.isOpen)render();
  }
  function saveGuideProgress(actor,progress){
    const value={...progress,updatedAt:new Date().toISOString(),clientSaveId:Date.now()+':'+(++guideSaveSequence),dirty:actor!=='guest'&&actor!=='offline'};
    try{localStorage.setItem(guideStorageKey(actor),JSON.stringify(value));}catch{notify('浏览器暂不允许保存模式与教学设置。');}
    if(actor==='guest'||actor==='offline')return;
    void flushGuideProgress();
  }
  function maybeBeginnerGuide(){
    const viewer=window.SVCommunity?.viewer();
    if(prefs.appMode!=='full'||guideCloudStatus!=='ready'||!viewer||guideCloud?.status!=='pending'||guideCloud.guideVersion!==2||!localeChoiceConfirmed||audioPending||run||tuner||metro||chord||loopsPlaying||capture||capturePending||saving||$('#startup-layer')||$('#welcome-layer')||$('dialog[open]')||window.SVTutorial?.isOpen||window.SVTutorial?.isCoaching)return false;
    const key=viewer.id+':2';if(guideOpened.has(key)||guideProgress().status!=='pending')return false;
    guideOpened.add(key);page='learn';history.replaceState(null,'','#learn');render();setBackgroundInert(false);$('#main').focus({preventScroll:true});return true;
  }
  function audioPermissionNotice(){notify(({zh:'请先完成或取消麦克风授权，再查看教学。',en:'Finish or cancel microphone permission before opening the guide.',ja:'マイクの許可を完了または取り消してから、説明を開いてください。',de:'Schließe die Mikrofonfreigabe ab oder brich sie ab, bevor du die Anleitung öffnest.'})[prefs.lang]);}
  function showTutorial(restart=false){
    if(audioPending){audioPermissionNotice();return;}
    if(!window.SVTutorial){setBackgroundInert(false);$('#main').focus({preventScroll:true});notify('操作没有完成，请重试。');return;}
    let actor=guideActor();const progress=restart?{step:0}:guideProgress();window.SVTutorial.open({lang:prefs.lang,region:prefs.region,brand:brand(),step:progress.step,onOpen(){setBackgroundInert(true);},onProgress(value){const current=guideActor();if(actor==='guest'&&current!=='guest'&&guideCloud?.status==='pending')actor=current;saveGuideProgress(actor,value);},async beforeAdvance(){if(audioPending){audioPermissionNotice();return false;}if(capture||capturePending||saving){notify('请先停止并保存录制，再切换模式或查看教学。');return false;}await finishPractice();engine.stopTuner();engine.stop();tuner=false;metro=false;chord=null;return true;},onFinish(status){prefs.tutorialVersion=1;prefs.tutorialStatus=status;prefs.tutorialAuto=false;const saved=persist();const auto=document.querySelector('[data-pref="tutorialAuto"]');if(auto)auto.checked=false;setBackgroundInert(false);$('#main').focus({preventScroll:true});if(page==='learn')render();if(!saved)notify('浏览器暂不允许保存模式与教学设置。');else if(status==='completed')notify('教学已完成');else if(status==='skipped')notify('教学已跳过，可在设置中重新查看。');},async navigate(id){if(page!==id){history.pushState(null,'','#'+id);await navigate(id);}else render();}});
  }
  function continueAfterWelcome(){if(maybeBeginnerGuide())return;if(prefs.tutorialAuto&&prefs.tutorialVersion!==1){page='learn';history.replaceState(null,'','#learn');render();prefs.tutorialVersion=1;persist();setBackgroundInert(false);$('#main').focus({preventScroll:true});}else{setBackgroundInert(false);$('#main').focus({preventScroll:true});}}
  window.addEventListener('sv-offline-status',updateOfflineUI);
  window.addEventListener('online',()=>{updateOfflineUI();guideRetryAttempts=0;void flushGuideProgress();if(prefs.appMode==='full')window.SVCommunity?.connect(communityContext())?.catch(()=>{});});window.addEventListener('offline',updateOfflineUI);
  function home(){
    const duration=svState.sessions.filter(s=>today(s.at)).reduce((n,s)=>n+s.duration,0),goal=svState.userPractice?.dailyGoal||20,ratio=Math.min(1,duration/60/goal),recent=svState.sessions.slice(0,3);
    const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const total=svState.sessions.filter(s=>new Date(s.at).toDateString()===d.toDateString()).reduce((n,s)=>n+s.duration/60,0);return {label:new Intl.DateTimeFormat(localeTag(),{weekday:'short'}).format(d),total};});
    return `${pageHeading('今天，让音乐近一点。','一首旋律，一段专注，属于你的练习时间。',`<span class="badge">${date(new Date())} · ${E(regions[prefs.region])}</span>`)}<section class="home-tuner-card"><div class="home-tuner-icon">${icon('activity')}</div><div class="home-tuner-copy"><span class="eyebrow">G · D · A · E</span><h3>调音器</h3><p>先调音，再开始练习。</p></div>${goButton('打开调音器','tuner','arrow-up-right','primary')}</section><div class="grid-two home-top"><section class="hero"><div class="hero-copy"><span class="eyebrow">YOUR NEXT MOMENT</span><h2>${recent.length?'继续你的旋律':'从第一段旋律开始'}</h2><p><span data-i18n-ignore>${E(title(song()))}</span><br>放慢一点，把每一个音拉得更从容。</p><div class="hero-actions">${goButton('进入练习','practice','play','primary')}${goButton('发现曲目','library','arrow-right','secondary')}</div><span class="help-text">无需连接琴，即可试听与看谱练习</span></div><div class="hero-visual"><img src="violin.png" alt="SmartVio 电子小提琴概念外观"><span class="concept-label">概念外观 · 非实物样机</span></div></section><section class="panel goal-panel"><div class="panel-header"><h3>今日练习</h3><button class="icon-button" data-go="profile" aria-label="设置练习目标">${icon('ellipsis')}</button></div><div class="goal-ring" style="--progress:${Math.round(ratio*360)}deg"><div class="goal-number"><strong>${(duration/60).toFixed(1)}</strong><span>/ ${goal} 分钟</span></div></div><div class="goal-stats"><span>${svState.sessions.filter(s=>today(s.at)&&s.inputRoute==='microphone').length} 次跟奏</span><span>${svState.sessions.filter(s=>today(s.at)&&s.inputRoute!=='microphone').length} 次聆听</span></div><div class="week-chart">${days.map(d=>`<div class="week-day"><div class="week-bar" title="${d.total.toFixed(1)} 分钟" style="height:${Math.max(3,Math.min(44,d.total*3))}px"></div><span>${d.label}</span></div>`).join('')}</div><p class="help-text">统计当前浏览器保存的练习与聆听记录</p></section></div><div class="quick-tools">${[['metronome','timer','节拍器','节拍与速度独立设置。'],['tones','sliders-horizontal','挑一个音色','找到喜欢的声音'],['studio','mic','录一段灵感','留住这一刻'],['device','bluetooth','连接我的琴','查看设备与路由']].map(([id,ic,h,p])=>`<button class="tool-tile" data-go="${id}"><span class="tile-icon">${icon(ic)}</span><span><strong>${h}</strong><small>${p}</small></span>${icon('chevron-right')}</button>`).join('')}</div><div class="section-header"><div><span class="eyebrow">A LITTLE EVERY DAY</span><h3>选一首，开始拉琴</h3></div><button class="link-button" data-go="library">查看曲库 ${icon('arrow-right')}</button></div><div class="song-grid">${svState.songs.filter(s=>songAvailable(s)&&!window.SVCommunity?.isSongHidden(s.id)).slice(0,6).map(songCard).join('')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h3>最近练习</h3><button class="link-button" data-go="profile">全部记录 ${icon('arrow-up-right')}</button></div>${recent.map(r=>`<div class="activity-row"><span class="activity-icon">${icon(r.inputRoute==='microphone'?'mic':'headphones')}</span><div class="activity-left"><strong data-i18n-ignore>${E(sessionTitle(r))}</strong><small>${date(r.at)} · ${kindName(r)}</small></div><span class="activity-value">${seconds(r.duration)}</span></div>`).join('')||empty('还没有练习记录','完成一次聆听或跟奏后，会显示在这里。')}</section><section class="course-banner"><span class="eyebrow">A GOOD START</span><h3>从持琴到第一首旋律</h3><p>认识空弦、放松运弓、慢速分句。<br>按照自己的节奏，建立演奏习惯。</p>${goButton('查看学习路径','learn','graduation-cap','secondary')}</section></div>`;
  }
  function regionalSong(s){return s.collection==='regional'&&(s.originCountry?s.originCountry===prefs.region:Array.isArray(s.regions)&&s.regions.includes(prefs.region));}
  function songAvailable(s){return s.category==='custom'||s.collection==='global'||regionalSong(s)||Array.isArray(s.regions)&&s.regions.includes(prefs.region);}
  function filteredSongs(){const q=query.normalize('NFKC').trim().toLocaleLowerCase();return svState.songs.filter(s=>{
    const inScope=prefs.libraryScope==='all'||prefs.libraryScope==='global'&&s.collection==='global'||prefs.libraryScope==='regional'&&regionalSong(s);
    const text=[title(s),s.title,s.author,s.originalAttribution,...['zh','en','ja','de'].map(lang=>s.titles?.[lang])].filter(value=>typeof value==='string').join(' ').normalize('NFKC').toLocaleLowerCase();
    return !window.SVCommunity?.isSongHidden(s.id)&&songAvailable(s)&&inScope&&(category==='all'||category==='favorites'&&prefs.favorites.includes(s.id)||s.category===category)&&(!q||text.includes(q));
  }).sort((a,b)=>(Number(b.catalogVersion)||0)-(Number(a.catalogVersion)||0));}
  function librarySubline(rows){return `${rows.length} ${T('首曲目')} · ${T(regions[prefs.region])} · ${T(({all:'全部',regional:'本国特色',global:'全球通用'})[prefs.libraryScope])}`;}
  function library(){const rows=filteredSongs();return `${pageHeading('找到下一首想拉的旋律','收藏喜欢的曲目，用自己的速度练习。',button(listView?'卡片视图':'列表视图','list-view',listView?'layout-grid':'list','secondary small'))}<div class="library-toolbar"><label class="search-box">${icon('search')}<input id="song-search" type="search" value="${E(query)}" placeholder="搜索曲名或作者" aria-label="搜索曲目"></label><div class="library-filter-controls"><div class="library-collection-tabs" role="group" aria-label="曲库范围">${[['all','全部'],['regional','本国特色'],['global','全球通用']].map(([id,label])=>`<button class="collection-tab ${prefs.libraryScope===id?'active':''}" data-action="library-scope" data-id="${id}" aria-pressed="${prefs.libraryScope===id}">${E(T(label))}</button>`).join('')}</div><div class="pill-tabs">${[['all','全部曲目'],['beginner','入门'],['classic','经典'],['folk','民谣'],['favorites','我的收藏']].map(([id,label])=>`<button class="pill-tab ${category===id?'active':''}" data-action="category" data-id="${id}" aria-pressed="${category===id}">${label}</button>`).join('')}</div></div></div><p class="library-subline" data-i18n-ignore>${E(librarySubline(rows))}</p><p class="library-source-note">${E(T('练习短版仅节选旋律；来源核对不等于全球发行授权。'))}</p><div id="song-results" class="${listView?'song-list':'song-grid'}">${libraryRows(rows)}</div>`;}
  function libraryRows(rows){return rows.map((s,i)=>listView?`<article class="song-list-item"><span class="serial">${String(i+1).padStart(2,'0')}</span><span class="song-list-cover" aria-hidden="true">${songImage(s)||icon('music-2')}</span><div class="activity-left"><button class="song-title" data-i18n-ignore data-action="choose-song" data-id="${E(s.id)}">${E(title(s))}</button><small><span data-i18n-ignore>${E(s.category==='custom'?s.author:T(s.author))}</span> · ${E(T(catNames[s.category]||'自建'))}</small></div><div class="song-list-evidence">${songBadges(s)}${sourceButton(s)}</div><button class="favorite ${prefs.favorites.includes(s.id)?'active':''}" data-action="favorite" data-id="${E(s.id)}" data-i18n-ignore aria-label="${E(T('收藏'))} ${E(title(s))}">${icon('heart')}</button>${button('练习','choose-song','play','small primary',`data-id="${E(s.id)}"`)}</article>`:songCard(s,i)).join('')||empty('没有找到曲目','换一个关键词或分类试试。','search');}
  function scoreSVG(score){const width=920,barsPerRow=4,barW=200,left=75,rows=Math.ceil(score.barCount/barsPerRow),height=Math.max(154,rows*122+28);let shapes='';for(let row=0;row<rows;row++){const top=38+row*122;for(let l=0;l<5;l++)shapes+=`<line x1="25" y1="${top+l*12}" x2="895" y2="${top+l*12}" stroke="currentColor" opacity=".28"/>`;shapes+=`<text x="29" y="${top+40}" font-size="55" font-family="Georgia,serif">𝄞</text>`;for(let b=0;b<4&&row*4+b<score.barCount;b++){const x=left+b*barW;shapes+=`<text class="bar-label" x="${x}" y="${top-14}">${row*4+b+1}</text><line x1="${x+barW-9}" y1="${top}" x2="${x+barW-9}" y2="${top+48}" stroke="currentColor" opacity=".35"/>`;}}
    for(const n of score.events){const row=Math.floor((n.bar-1)/barsPerRow),top=38+row*122,bar=(n.bar-1)%4,x=left+bar*barW+15+(n.startTick%score.ticksPerBar)/score.ticksPerBar*(barW-36),p=SVScoreModel.staffPosition(prefs.semitone?SVScoreModel.transposeName(n.pitch,prefs.semitone):n.pitch,top,6);const outside=n.bar<prefs.from||(prefs.to>0&&n.bar>prefs.to);if(!p){shapes+=`<text data-note="${n.sourceIndex}" x="${x}" y="${top+30}" font-size="26">𝄽</text>`;continue;}const open=n.beats>=2;shapes+=`<g class="staff-note" data-note="${n.sourceIndex}" opacity="${outside?.28:1}">${p.ledgerYs.map(y=>`<line x1="${x-11}" x2="${x+11}" y1="${y}" y2="${y}" stroke="currentColor"/>`).join('')}${p.accidental?`<text x="${x-21}" y="${p.y+5}" font-size="19">${p.accidental==='#'?'♯':'♭'}</text>`:''}<ellipse cx="${x}" cy="${p.y}" rx="7" ry="5" transform="rotate(-18 ${x} ${p.y})" fill="${open?'var(--paper,#fff)':'currentColor'}" stroke="currentColor" stroke-width="1.6"/>${n.beats<4?`<line x1="${x+6}" x2="${x+6}" y1="${p.y}" y2="${p.y-29}" stroke="currentColor" stroke-width="1.7"/>`:''}${n.beats<1?`<path d="M ${x+6} ${p.y-29} q 15 10 4 20" fill="none" stroke="currentColor" stroke-width="2"/>`:''}</g>`;}
    return `<svg class="score-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${E(title(song()))}，${score.barCount}小节，${prefs.meter}拍五线谱">${shapes}</svg>`;
  }
  function practice(){const {score,range}=rangeModel();return `${pageHeading('把一首曲子，练成自己的声音。','先听，再慢练。选定段落，逐句推进。',goButton('更换曲目','library','library','secondary small'))}<div class="practice-shell"><section class="panel score-panel"><div class="score-top"><span class="song-score-icon" aria-hidden="true">${songImage(song())||icon('music-2')}</span><div class="activity-left"><h3 data-i18n-ignore>${E(title(song()))}</h3><p><span data-i18n-ignore>${E(song().category==='custom'?song().author:T(song().author))}</span> · ${E(T('拍号'))} ${prefs.meter} · ${score.barCount} ${E(T('小节'))}</p></div><button class="favorite ${prefs.favorites.includes(song().id)?'active':''}" data-action="favorite" data-id="${E(song().id)}" aria-label="收藏当前曲目">${icon('heart')}</button></div><div class="score-body"><div class="row between"><span class="badge">${prefs.from}–${prefs.to||score.barCount} 小节${prefs.repeat?' · 重复聆听':''}</span><span class="help-text">谱面与播放共用时间刻度</span></div><div class="score-scroll">${scoreSVG(score)}</div><div class="note-strip">${range.events.map(n=>`<span class="note-card" data-note="${n.sourceIndex}"><strong>${E(SVScoreModel.transposeName(n.pitch,prefs.semitone))}</strong><small>${n.beats} ${E(T('拍'))}</small></span>`).join('')}</div><div class="score-caption"><span>${E(T(isExcerpt(song())?'练习短版 · 节选旋律':'开发候选谱本 · 尚未核验正式发行权利'))}</span>${sourceButton(song())}</div></div><div class="score-progress"><span id="play-progress" style="width:0%"></span></div><div class="transport"><div class="transport-main">${button('示范聆听','play','play','primary')}${button('跟奏练习','mic-practice','mic','secondary')}${button('停止','stop','square','secondary small')}</div><div class="transport-bpm"><strong>${prefs.bpm}</strong><small>BPM</small><span id="play-clock">00:00</span></div></div><div class="score-live" id="practice-live" role="status">准备好了，从第 ${prefs.from} 小节开始。</div></section><aside class="panel settings-panel practice-settings"><details class="compact-details" ${practiceSettingsOpen?'open':''}><summary><strong>练习设置</strong>${icon('sliders-horizontal')}</summary><div class="practice-settings-body"><label>速度 <span>${prefs.bpm} BPM</span><input type="range" min="30" max="240" value="${prefs.bpm}" data-pref="bpm" aria-label="练习速度"></label><div class="ab-grid"><label>拍号<select data-pref="meter" aria-label="拍号">${meterOptions().map(v=>`<option ${v===prefs.meter?'selected':''}>${v}</option>`).join('')}</select></label><label>移调<select data-pref="semitone" aria-label="移调">${Array.from({length:13},(_,i)=>i-6).map(n=>`<option value="${n}" ${n===prefs.semitone?'selected':''}>${n>0?'+':''}${n} 半音</option>`).join('')}</select></label></div><div class="section-header"><strong>A–B 分段</strong><span class="help-text">按小节</span></div><div class="ab-grid"><label>从<input type="number" min="1" max="${score.barCount}" value="${prefs.from}" data-pref="from" aria-label="起始小节"></label><label>到<input type="number" min="1" max="${score.barCount}" value="${prefs.to||score.barCount}" data-pref="to" aria-label="结束小节"><small>共 ${score.barCount} 小节</small></label></div><label class="row"><input type="checkbox" data-pref="repeat" ${prefs.repeat?'checked':''}>重复聆听选定段落</label><div class="mini-sound">${icon('audio-lines')}<span>${E(toneNames[prefs.preset][0])}</span><button class="link-button" data-go="tones">更换</button></div>${goButton('调音器','tuner','activity','secondary')}<p class="help-text">跟奏使用单音麦克风检测，80–3000 Hz。结果仅作练习参考，尚未完成实琴标定。</p></div></details></aside></div><section class="panel chord-section"><div class="panel-header"><div><h3>给旋律一点伴奏</h3><p>原创合成和弦 · 点击开启，再次点击停止</p></div><select id="chord-style" aria-label="伴奏方式"><option value="arp">分解和弦</option><option value="strum">扫弦</option><option value="pad">长音铺底</option></select></div><div class="chord-pads">${['C','G','Am','F','Em','Dm','G7','A7'].map(c=>`<button class="chord-pad ${chord===c?'active':''}" data-action="chord" data-id="${c}" aria-pressed="${chord===c}">${c}</button>`).join('')}</div><p class="help-text">麦克风跟奏会关闭参考播放与伴奏，减少扬声器串音。</p></section>`;}
  function tones(){return `${pageHeading('找到你的声音。','从干净的原声，到带一点空间的个人音色。',button('保存当前预设','save-preset','bookmark','primary'))}<section class="preset-preview"><span class="preset-icon">${icon(toneNames[prefs.preset][1])}</span><div><span class="eyebrow">CURRENT SOUND</span><h3>${E(toneNames[prefs.preset][0])}</h3><p>${E(T(toneNames[prefs.preset][2]))} · 浏览器合成预览</p></div>${button('试听旋律','audition','play','primary')}${button('停止','stop-audio','square','secondary small')}</section><div class="preset-grid">${engine.presets.map(p=>`<button class="preset-card ${prefs.preset===p?'selected':''}" data-action="preset" data-id="${p}" aria-pressed="${prefs.preset===p}"><span class="preset-icon">${icon(toneNames[p][1])}</span>${prefs.preset===p?`<span class="checkmark">${icon('check')}</span>`:''}<strong>${E(toneNames[p][0])}</strong><small>${E(toneNames[p][2])}</small></button>`).join('')}</div><div class="section-header"><div><span class="eyebrow">A LITTLE CHARACTER</span><h3>声音细节</h3></div><span class="badge">固定效果路由</span></div><div class="effect-chain">${[['compression','压缩','收稳动态'],['delay','延时','加入回声'],['reverb','混响','增加空间'],['volume','音量','控制输出']].map(([k,h,p],i)=>`<section class="effect-card"><span class="effect-number">0${i+1}</span><h3>${h}</h3><p>${p}</p><label><span id="effect-${k}">${Math.round(prefs.effects[k]*100)}%</span><input type="range" min="0" max="100" value="${Math.round(prefs.effects[k]*100)}" data-effect="${k}" aria-label="${h}"></label></section>`).join('')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h3>我的预设</h3>${button('导出','export-presets','download','secondary small')}</div>${(svState.presets||[]).map(p=>`<div class="saved-row"><span class="tile-icon">${icon('bookmark')}</span><div class="activity-left"><strong data-i18n-ignore>${E(p.name)}</strong><small>${E(T(toneNames[p.preset]?.[0]||p.preset))} · <span data-i18n-ignore>${E(p.group||T('未分组'))}</span> · ${date(p.at)}</small></div>${button('应用','load-preset','check','secondary small',`data-id="${E(p.id)}"`)}${button('改名','rename-preset','pencil','secondary small',`data-id="${E(p.id)}"`)}<button class="icon-button" data-action="delete-preset" data-id="${E(p.id)}" data-i18n-ignore aria-label="${E(T('删除'))} ${E(p.name)}">${icon('trash-2')}</button></div>`).join('')||empty('保存一个喜欢的音色','你的音色与效果参数会保存在当前手机浏览器。','bookmark')}</section><section class="panel"><div class="panel-header"><h3>琴端音色</h3><span class="badge pending">待接入</span></div><p>现在的音色控制作用于浏览器示范与合成录音。连接琴后，需要确认型号和 DSP 协议才能写入设备。</p>${goButton('查看设备能力','device','bluetooth','secondary')}<p class="help-text">九种音色为原创合成音源，未使用竞品音色包或采样。</p></section></div>`;}
  const trackColors=['#b97a4d','#6d9381','#9386af','#648dac'];
  function recordUrl(row){if(!urls.has(row.id))urls.set(row.id,URL.createObjectURL(row.blob));return urls.get(row.id);}
  function waveform(row){const peaks=waveCache.get(row?.id);if(!row)return `<div class="wave-empty">录一段声音，让灵感从这里开始</div>`;if(!peaks)return `<div class="wave-empty">读取真实音频波形…</div>`;if(peaks.error)return `<div class="wave-empty">${E(peaks.error)}</div>`;return `<svg viewBox="0 0 600 70" preserveAspectRatio="none" role="img" aria-label="已录音频的相对波形（按峰值归一显示）">${peaks.map((v,i)=>`<line x1="${i*6+3}" x2="${i*6+3}" y1="${35-v*30}" y2="${35+v*30}" stroke="currentColor" stroke-width="3" stroke-linecap="round"/>`).join('')}</svg>`;}
  function studio(){const rows=media.filter(r=>r.kind==='loop'),other=media.filter(r=>r.kind!=='loop');return `${pageHeading('把灵感，留在这里。','四轨循环、独立录音与视频，让每一次尝试有迹可循。',button('保存工程','save-project','folder-plus','primary'))}<section class="panel studio-header"><div class="studio-transport">${button('播放四轨','play-loops','play','primary')}${button('停止','stop-loops','square','secondary small')}<span class="studio-time" id="studio-time">${loopsPlaying?'回放中':'00:00'}</span></div><div class="row"><span class="badge">${prefs.bpm} BPM</span><label>录制来源<select data-pref="source" aria-label="录制来源"><option value="synth" ${prefs.source==='synth'?'selected':''}>浏览器合成</option><option value="microphone" ${prefs.source==='microphone'?'selected':''}>真实麦克风</option></select></label><label>工程小节<select data-pref="barCount" aria-label="工程小节数">${[1,2,4,8].map(n=>`<option value="${n}" ${prefs.barCount===n?'selected':''}>${n} 小节</option>`).join('')}</select></label></div></section><p class="help-text">轨道同一时刻启动，各自按录制长度循环；工程小节是备注，尚未做录音量化与延迟补偿。</p><div class="track-grid">${Array.from({length:4},(_,i)=>{const row=rows.find(r=>r.trackIndex===i),active=capture?.trackIndex===i;return `<section class="studio-track" style="--track-color:${trackColors[i]}"><div class="track-title"><span class="track-color">0${i+1}</span><strong>轨道 ${i+1}</strong><small>${row?seconds(row.duration):'空轨'}</small></div><div class="waveform" data-wave="${row?.id||''}">${waveform(row)}</div><div class="track-controls"><div class="track-buttons"><button class="icon-button record ${active?'active':''}" data-action="${active?'stop-record':'record-loop'}" data-track="${i}" aria-label="${active?'停止':'录制'}轨道 ${i+1}" ${capturePending||saving?'disabled':''}>${icon(active?'square':'circle')}</button><button class="icon-button ${prefs.mutes[i]?'active':''}" data-action="mute-track" data-track="${i}" aria-label="${prefs.mutes[i]?'取消静音':'静音'}轨道 ${i+1}" aria-pressed="${prefs.mutes[i]}">${icon(prefs.mutes[i]?'volume-x':'volume-2')}</button><button class="icon-button" data-action="download-media" data-id="${row?.id||''}" aria-label="下载轨道 ${i+1}" ${!row?'disabled':''}>${icon('download')}</button><button class="icon-button" data-action="clear-track" data-track="${i}" aria-label="清空轨道 ${i+1}" ${!row?'disabled':''}>${icon('trash-2')}</button></div><label class="track-level"><input type="range" data-level="${i}" min="0" max="100" value="${Math.round(prefs.levels[i]*100)}" aria-label="轨道 ${i+1} 音量"><span>${Math.round(prefs.levels[i]*100)}%</span></label><small>${row?(row.persisted?'已存本机':'仅内存，需下载'):'等待录制'}</small></div></section>`;}).join('')}</div><div id="record-status" class="record-status" role="status">${capture?'正在录制，点击停止后保存。':capturePending?'等待录制权限…':'准备录制。浏览器合成来源会播放当前练习旋律。'}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h3>录下你的演奏</h3>${icon('mic')}</div><p>独立录音不覆盖循环轨。视频会单独请求相机与麦克风。</p><div class="record-controls">${button('录音','record-audio','mic','secondary')}${button('录视频','record-video','video','secondary')}${button('停止并保存','stop-record','square','secondary small')}</div><video id="camera-preview" class="camera-preview" muted playsinline hidden></video><p class="help-text">媒体只保存在当前浏览器与地址。请下载备份；没有云端音频上传。</p></section><section class="panel"><div class="panel-header"><h3>我的工程</h3><span class="badge">${(svState.projects||[]).length} 个</span></div>${(svState.projects||[]).map(p=>`<div class="saved-row"><span class="tile-icon">${icon('folder')}</span><div class="activity-left"><strong data-i18n-ignore>${E(p.name)}</strong><small>${p.trackIds.length} 轨 · ${p.bpm} BPM · ${p.barCount} 小节</small></div>${button('打开','load-project','folder-open','secondary small',`data-id="${E(p.id)}"`)}<button class="icon-button" data-action="delete-project" data-id="${E(p.id)}" data-i18n-ignore aria-label="${E(T('删除工程'))} ${E(p.name)}">${icon('trash-2')}</button></div>`).join('')||empty('保存你的第一个工程','工程保存参数与本机轨道引用；音频另存浏览器。','folder')}</section></div><section class="panel studio-library"><div class="panel-header"><h3>我的录音与视频</h3><span class="badge">${other.length} 段</span></div>${other.map(r=>`<article class="media-item"><span class="tile-icon">${icon(r.kind==='video'?'video':'mic')}</span><div class="activity-left"><strong data-i18n-ignore>${E(r.name||T('未命名录音'))}</strong><small>${seconds(r.duration)} · ${r.source==='synth'?'浏览器合成':'麦克风'} · ${r.persisted?'已存本机':'仅内存'}</small><${r.kind==='video'?'video':'audio'} controls preload="metadata" src="${recordUrl(r)}"></${r.kind==='video'?'video':'audio'}></div><button class="icon-button" data-action="download-media" data-id="${E(r.id)}" data-i18n-ignore aria-label="${E(T('下载'))} ${E(r.name)}">${icon('download')}</button><button class="icon-button" data-action="delete-media" data-id="${E(r.id)}" data-i18n-ignore aria-label="${E(T('删除'))} ${E(r.name)}">${icon('trash-2')}</button></article>`).join('')||empty('还没有录音','录下一个乐句，停止后即可回听与下载。','mic')}</section>`;}
  function tunerPage(){return `${pageHeading('先调准，再出发。','四根弦，一次平静而准确的开始。',`<span class="badge">单音检测 · 80–3000 Hz</span>`)}<div class="tuner-layout"><section class="panel tuner-display"><span class="eyebrow">CHROMATIC TUNER</span><div class="tuner-note" id="tuner-note">—</div><div class="tuner-hz" id="tuner-hz">尚未检测声音</div><div class="tuner-scale"><div class="tuner-tick">−50</div><div class="tuner-tick">−25</div><div class="tuner-tick">0</div><div class="tuner-tick">+25</div><div class="tuner-tick">+50</div><div class="tuner-needle" id="tuner-needle" style="left:50%"></div></div><div class="tuner-feedback" id="tuner-feedback" role="status">允许麦克风后，慢拉一根空弦。</div><div class="string-buttons">${['G3','D4','A4','E5'].map(n=>`<button class="string-button ${prefs.string===n?'active':''}" data-action="reference" data-id="${n}" aria-pressed="${prefs.string===n}"><strong>${n.slice(0,-1)}</strong><small>${SVScoreModel.frequency(n,prefs.a4,0).toFixed(1)} Hz</small>${icon('volume-2')}</button>`).join('')}</div>${button(tuner?'停止检测':'开始麦克风调音',tuner?'stop-tuner':'start-tuner',tuner?'square':'mic','primary')}<p class="help-text">点击弦按钮播放参考音。参考音与练习移调独立，麦克风检测尚未完成实琴标定。</p></section><div class="stack"><section class="panel"><div class="panel-header"><h3>调音设置</h3>${icon('sliders-horizontal')}</div><label>A4 基准频率<div class="row"><input type="number" data-pref="a4" min="400" max="480" value="${prefs.a4}" aria-label="A4基准频率"><span>Hz</span></div></label><label>环境噪声门限<input type="range" id="noise-gate" min="1" max="50" value="8" aria-label="环境噪声门限"></label><p class="help-text">嘈杂环境请提高门限；检测不到时靠近麦克风并慢拉单音。</p></section><section class="panel"><h3>节拍器</h3><p>节拍与速度独立设置。</p>${goButton('节拍器','metronome','timer','secondary')}</section></div></div>`;}
  function metronomePage(){return `${pageHeading('节拍器','节拍与速度独立设置。',goButton('调音器','tuner','activity','secondary small'))}<div class="metronome-page"><section class="panel"><div class="panel-header"><h3>节拍器</h3><span class="metronome-pulse ${metro?'active':''}" id="metro-pulse"></span></div><div class="tempo-display"><strong>${prefs.bpm}</strong><span class="tempo-unit">BPM</span></div><div class="tempo-adjust">${button('− 5','tempo-down','minus','secondary small')}${button('+ 5','tempo-up','plus','secondary small')}<select data-pref="meter" aria-label="节拍器拍号">${['2/4','3/4','4/4','6/8'].map(m=>`<option ${m===prefs.meter?'selected':''}>${m}</option>`).join('')}</select></div>${button(metro?'停止节拍':'开始节拍',metro?'stop-metro':'start-metro',metro?'square':'play','primary')}<p class="help-text">第一拍为重音，音频时钟负责安排节拍。</p></section></div>`;}
  function device(){return `${pageHeading('你的琴，你的连接方式。','控制、录音和 MIDI，分别查看真实状态。',`<span class="badge pending">琴端联调待完成</span>`)}<div class="device-layout"><section class="device-card"><img src="violin.png" alt="电子小提琴概念外观"><span class="concept-label">概念外观 · 非实物样机</span><div class="device-summary"><span class="eyebrow">SMARTVIO INSTRUMENT</span><h3>我的电子小提琴</h3><span class="badge">未连接真实设备</span><p>设备型号、固件、电量与时延均未取得实测值。</p>${button('查看连接步骤','connection-help','bluetooth','primary')}</div></section><div class="stack"><section class="panel"><div class="panel-header"><h3>连接与路由</h3>${icon('cable')}</div>${[['bluetooth','参数控制','BLE 协议和设备握手待接入','待接入'],['mic','音频输入','录音页可请求系统麦克风；USB 声卡由系统管理','由系统选择'],['piano','MIDI 端口','枚举真实输入与输出端口；音符收录、编辑与文件导出见 MIDI 工作台',midiPorts.length?`${midiPorts.length} 个端口`:'未检测']].map(([ic,h,p,status])=>`<div class="route-row"><span class="tile-icon">${icon(ic)}</span><div class="activity-left"><strong>${h}</strong><small>${p}</small></div><span class="badge">${status}</span></div>`).join('')}${button('检测 MIDI 端口','detect-midi','refresh-cw','secondary')}<div id="midi-result" class="help-text">${midiPorts.map(p=>'<span data-i18n-ignore>'+E(p.name||T('未命名端口'))+'</span>').join(' · ')}</div></section><section class="panel"><div class="panel-header"><h3>设备能力</h3><span class="badge">等待型号确认</span></div><div class="capability-grid">${[['sliders-horizontal','琴内 DSP 音色'],['download','固件升级'],['audio-lines','设备内录'],['activity','端到端时延实测']].map(([ic,h])=>`<div class="capability">${icon(ic)}<strong>${h}</strong><span class="badge pending">待硬件验证</span></div>`).join('')}</div><p class="help-text">网页可用功能：参考音、示范播放、麦克风调音、浏览器录音与四轨回放。</p></section></div></div><section class="panel"><div class="panel-header"><h3>开始使用的三个步骤</h3>${goButton('学习路径','learn','graduation-cap','secondary small')}</div><div class="grid-three">${[['01','先建立有线监听','连接琴与耳机，确认琴本身可以发声。'],['02','选择录音输入','在浏览器权限与系统输入中选择麦克风或 USB 声卡。'],['03','调音，再练一句','确认 G / D / A / E，进入练习页慢速跟奏。']].map(([n,h,p])=>`<div><span class="eyebrow">${n}</span><h4>${h}</h4><p>${p}</p></div>`).join('')}</div></section>`;}
  function learn(){const labels={zh:['更多练习与按钮说明','原有九个练习和界面导览，按需查看。'],en:['More exercises and button guide','Your original nine exercises and interface guide, when needed.'],ja:['練習とボタンの説明','これまでの9つの練習と画面ガイドを必要な時に確認できます。'],de:['Weitere Übungen und Bedienhilfe','Die bisherigen neun Übungen und die Bedienhilfe bei Bedarf.']}[prefs.lang];return '<div id="learning-path-host" data-i18n-ignore></div><details class="panel learning-extra" data-i18n-ignore><summary>'+E(labels[0])+'</summary><p>'+E(labels[1])+'</p>'+legacyLearn()+'</details>';}
  function legacyLearn(){const done=new Set(svState.userPractice?.completedLessons||[]);return `${window.SVTutorial?.entry({lang:prefs.lang,progress:guideProgress()})||''}${pageHeading('每一次小进步，都算数。','从零开始到独立演奏，跟着路径练习。',`<span class="badge">已完成 ${done.size} / 9</span>`)}<div class="grid-three">${courses.map(c=>`<section class="panel lesson-card"><img class="learn-course-photo" src="learning/${({begin:'welcome',melody:'phrase',create:'record'})[c.id]}.jpg" alt="" width="960" height="640" loading="lazy"><span class="lesson-icon">${icon(c.icon)}</span><span class="eyebrow">${c.label}</span><h3>${c.title}</h3><div class="lesson-list">${c.lessons.map(([id,h,p],i)=>`<div class="lesson-item"><button class="icon-button" data-action="lesson-toggle" data-id="${id}" aria-label="${E(T(done.has(id)?'取消完成':'标记完成'))} ${E(T(h))}" aria-pressed="${done.has(id)}">${icon(done.has(id)?'circle-check':'circle')}</button><button class="link-button" data-action="lesson" data-id="${id}"><span>${i+1}. ${E(T(h))}</span>${icon('chevron-right')}</button></div>`).join('')}</div><p class="help-text">原创文字练习 · 自行标记进度</p></section>`).join('')}</div><section class="course-banner"><span class="eyebrow">PUT IT INTO PRACTICE</span><h3>看完一步，就练一句。</h3><p>把学习内容放到实际演奏中。先慢练，再记录，最后回听。</p>${goButton('开始练习','practice','play','primary')}</section>`;}
  function communityContext(){return {lang:prefs.lang,region:prefs.region,mode:prefs.appMode,legacyDrafts:svState.posts||[],media};}
  function community(){return window.SVCommunity?.render(communityContext())||empty('社区暂不可用','请联网刷新页面后重试，练习与调音仍可使用。','users');}
  function adminEntry(){
    if(prefs.appMode==='offline'||!window.SVCommunity?.viewer()?.isAdmin)return '';
    const copy={zh:['后台管理','审核帖子与评论，处理举报和社区设置。','打开管理端'],en:['Administration','Review posts and comments, reports and community settings.','Open administration'],ja:['管理画面','投稿・コメントの審査、通報とコミュニティ設定。','管理画面を開く'],de:['Verwaltung','Beiträge und Kommentare prüfen, Meldungen und Community verwalten.','Verwaltung öffnen']}[prefs.lang];
    return '<section class="panel community-admin-entry" data-i18n-ignore><h3>'+E(copy[0])+'</h3><p>'+E(copy[1])+'</p><a class="button secondary" href="/admin">'+E(copy[2])+'</a></section>';
  }
  function shop(){const currency={us:'USD',uk:'GBP',de:'EUR',jp:'JPY',fr:'EUR',cn:'CNY'}[prefs.region];return `${pageHeading('探索 SmartVio 的可能。','产品方向与概念外观，具体规格和价格待确认。',`<span class="badge pending">产品规划</span>`)}<div class="grid-three">${svState.products.map(p=>`<article class="panel product-card"><img src="${E(p.img||'violin.png')}" alt="${E(T(p.title.zh))} — ${E(T('概念外观 · 非实物'))}"><span class="badge pending">概念外观 · 非实物</span><h3>${E(T(p.title.zh))}</h3><p>${E(T(p.desc.zh))}</p><span class="price">价格待定</span>${button('查看产品方向','product-info','arrow-up-right','secondary',`data-id="${E(p.id)}"`)}</article>`).join('')}</div><div class="note-box"><strong>${E(regions[prefs.region])} · ${currency}</strong><p>此页用于验证产品信息布局。未接入真实支付、库存、物流和订阅权益。</p></div>`;}
  function profile(){const goal=svState.userPractice?.dailyGoal||20;return `${pageHeading('把琴房，设成你的习惯。','管理目标、界面与本地记录。',button('导出记录','export-data','download','secondary'))}${modePanel()}${adminEntry()}<section class="panel"><h3>功能可行性与验收报告</h3><div class="button-row"><a class="button secondary" href="reports/feasibility-20261015.html" target="_blank" rel="noopener">阅读报告</a><a class="button secondary" href="reports/SmartVio-feasibility-20261015.pdf" download>下载 PDF 报告</a></div></section><div class="profile-grid"><section class="panel"><div class="profile-title"><span class="avatar">SV</span><div><h3>我的手机琴房</h3><p class="profile-brand-line"><span class="profile-brand" data-brand-name data-i18n-ignore>${brandMarkup(brand())}</span><span class="profile-version"> · V16</span></p></div></div><div class="form-grid"><label>界面语言<select data-pref="lang" aria-label="界面语言">${[['zh','中文'],['en','English'],['ja','日本語'],['de','Deutsch']].map(([v,h])=>`<option value="${v}" ${prefs.lang===v?'selected':''}>${h}</option>`).join('')}</select></label><label>地区<select data-pref="region" aria-label="地区">${Object.entries(regions).map(([v,h])=>`<option value="${v}" ${prefs.region===v?'selected':''}>${h}</option>`).join('')}</select></label><label>每日练习目标<input id="daily-goal" type="number" min="1" max="240" value="${goal}" aria-label="每日练习目标"></label><label>外观<select data-pref="theme" aria-label="外观"><option value="light" ${prefs.theme==='light'?'selected':''}>浅色</option><option value="dark" ${prefs.theme==='dark'?'selected':''}>深色</option></select></label></div>${button('保存每日目标','save-goal','check','primary')}<div class="locale-settings-actions">${button('重新选择国家','country-settings','globe','secondary')}${button('开机动画','replay-startup','sparkles','secondary')}</div><p class="help-text">四种语言覆盖页面、操作提示与帮助。国家决定默认语言，你也可以单独更改语言。</p></section><section class="panel"><div class="panel-header"><h3>数据与保存</h3>${icon('hard-drive')}</div><div class="list-setting"><strong>${media.length} 段本机媒体</strong><span>当前浏览器地址的 IndexedDB</span></div><div class="list-setting"><strong>${svState.sessions.length} 次练习</strong><span>当前浏览器的练习与设置记录</span></div><div class="list-setting"><strong>练习备份 / 原生 App</strong><span>练习与音频仍在本机；社区内容单独保存云端。</span></div>${button('导出练习 CSV','export-csv','file-spreadsheet','secondary')}${button('清除当前浏览器数据','clear-dialog','trash-2','danger small')}<p class="help-text">JSON导出含练习、预设、工程与媒体清单，不含录音文件或私有笔记、反馈。删除前请下载录音，另行保留需要的笔记。浏览器清理可能移除记录。</p></section></div><section class="panel"><div class="panel-header"><h3>练习历史</h3><span class="badge">真实操作记录</span></div><div class="history-table">${table(['日期','曲目','方式','时长','参考结果'],svState.sessions.slice(0,30).map(r=>`<tr><td>${date(r.at)}</td><td data-i18n-ignore>${E(sessionTitle(r))}</td><td>${kindName(r)}</td><td>${seconds(r.duration)}</td><td>${r.score===null?'—':r.score+'% 音高覆盖'}</td></tr>`))}</div><p class="help-text">示范聆听不生成演奏成绩。跟奏记录保留输入来源、评分版本与段落范围。</p></section>`;}
  const views={home,library,practice,studio,performance:performanceView,midi:midiView,tones,tuner:tunerPage,metronome:metronomePage,device,learn,community,shop,profile};
  const baseHome=views.home,baseTones=views.tones,baseDevice=views.device,baseStudio=views.studio;
  views.studio=()=>baseStudio()+'<section class="panel"><label class="checkbox-row"><input type="checkbox" id="align-loops" data-pref="alignLoops" '+(prefs.alignLoops?'checked':'')+'>'+E(T('按工程长度循环'))+'</label><p>'+E(T('仅统一循环长度，补静音或截取播放副本；原始录音保留。'))+'</p></section>';
  views.home=()=>baseHome()+'<section class="panel"><div class="button-row">'+goButton('伴奏与弦乐','performance','music-4','secondary')+goButton('MIDI 工作台','midi','piano','secondary')+'</div></section>';
  views.tones=()=>baseTones()+presetExtras();views.device=()=>baseDevice()+bridgeControls();
  function render(){learningPath.unmount();window.SVCommunity?.deactivate?.();cloudCleanup?.dispose?.();if(typeof cloudCleanup==='function')cloudCleanup();cloudCleanup=null;midiStudio.unmount();performanceStudio.unmount();const settings=$('.practice-settings .compact-details');if(settings)practiceSettingsOpen=settings.open;const active=document.activeElement;const focusPref=active?.closest('.practice-settings')?active.dataset.pref:null;window.SVLocale?.setLanguage(prefs.lang,prefs.region);document.documentElement.dataset.theme=prefs.theme==='dark'?'dark':'light';document.documentElement.lang=prefs.lang;$('#page-title').textContent=nameOf(page);$('#page-kicker').textContent=nav.find(n=>n[0]===page)?.[7]||'';$('#desktop-nav').innerHTML=nav.map((n,i)=>`${i===9?'<div class="nav-divider"></div>':''}<button class="nav-button ${page===n[0]?'active':''}" data-go="${n[0]}" ${page===n[0]?'aria-current="page"':''}>${icon(n[6])}<span>${E(nameOf(n[0]))}</span>${page===n[0]?'<span class="nav-active-dot"></span>':''}</button>`).join('');$('#bottom-nav').innerHTML=[nav[0],nav[1],nav[2],nav[3]].map(n=>`<button class="${page===n[0]?'active':''}" data-go="${n[0]}" ${page===n[0]?'aria-current="page"':''}>${icon(n[6])}<span>${E(nameOf(n[0]))}</span></button>`).join('')+`<button data-action="menu" ${['performance','midi','tones','tuner','metronome','device','learn','community','shop','profile'].includes(page)?'class="active"':''}>${icon('grid-2x2')}<span>${({zh:'更多',en:'More',de:'Mehr',ja:'その他',fr:'Plus'})[prefs.lang]}</span></button>`;$('#main').innerHTML=views[page]();if(page==='community')window.SVCommunity?.activate();if(page==='learn')learningPath.mount($('#learning-path-host'),{lang:prefs.lang,onNotice:notify,onNavigate:async target=>{if(capture||capturePending||saving){notify(T('请先停止并保存录制。'));return;}await navigate(target);location.hash=target;}});if(page==='performance')performanceStudio.mount($('#performance-host'),{lang:prefs.lang});if(page==='midi')midiStudio.mount($('#midi-host'),{lang:prefs.lang});if(page==='tones')cloudCleanup=SVPresetCloud.mount('#preset-cloud',{lang:prefs.lang,mode:prefs.appMode,getPresets:()=>svState.presets,onRestore:restorePresets,onNotice:notify});updateDeviceStatus();icons();syncBrand();window.SVLocale?.translate(document.body);window.SVTutorial?.refreshCoach();queueMicrotask(maybeBeginnerGuide);if(focusPref)document.querySelector('[data-pref="'+focusPref+'"]')?.focus({preventScroll:true});if(page==='studio'){drawWaves();if(capture?.kind==='video'&&capture.recorder.stream){const preview=$('#camera-preview');preview.hidden=false;preview.srcObject=capture.recorder.stream;preview.play().catch(()=>{});}}}
  async function navigate(id){if(!views[id])id='home';const generation=++navigationId;captureGeneration++;if(capturePending)videoManager.cancel();engine.stopTuner();tuner=false;await finishPractice();engine.stop();metro=false;chord=null;loopsPlaying=false;if(capture)await stopRecord();if(generation!==navigationId)return;page=id;render();window.scrollTo(0,0);}
  async function refreshMedia(){media=await SVMediaStore.list();if(SVMediaStore.status().error?.code==='READ_FAILED')notify('本机媒体读取失败，请保留文件并稍后重试。');const ids=new Set(media.map(r=>r.id));for(const [id,url] of urls)if(!ids.has(id)){URL.revokeObjectURL(url);urls.delete(id);}return media;}
  async function drawWaves(){for(const row of media.filter(r=>r.kind==='loop')){if(page!=='studio')break;if(waveCache.has(row.id))continue;try{const context=new (window.AudioContext||window.webkitAudioContext)();try{const b=await context.decodeAudioData((await row.blob.arrayBuffer()).slice(0)),data=b.getChannelData(0),step=Math.max(1,Math.floor(data.length/100)),peaks=[];for(let i=0;i<100;i++){let max=0;for(let j=i*step;j<Math.min(data.length,(i+1)*step);j++)max=Math.max(max,Math.abs(data[j]));peaks.push(max);}const peak=Math.max(...peaks);waveCache.set(row.id,peak>0?peaks.map(v=>v/peak):peaks);}finally{await context.close();}}catch{waveCache.set(row.id,{error:'音频不能解码，仍可下载原文件'});}if(page==='studio'){const el=Array.from(document.querySelectorAll('[data-wave]')).find(e=>e.dataset.wave===row.id);if(el)el.innerHTML=waveform(row);}}}
  function updatePractice(i,elapsed,duration){document.querySelectorAll('[data-note]').forEach(el=>el.classList.toggle('current',Number(el.dataset.note)===i));const clock=$('#play-clock'),progress=$('#play-progress');if(clock)clock.textContent=seconds(elapsed);if(progress)progress.style.width=`${Math.min(100,elapsed/duration*100)}%`;}
  async function finishPractice(){const previous=run;run=null;runId++;loopRequest++;loopsPlaying=false;engine.stop();engine.stopTuner();if(!previous)return;clearInterval(previous.timer);if(previous.started===null)return;const elapsed=Math.min(previous.duration,(performance.now()-previous.started)/1000);if(elapsed<.5)return;let result=previous.coverage?SVScoreModel.coverageResult(previous.coverage):null;const valid=result?.validInputFraction>=.2;const scored=valid?result.score:null;const saved=await action({type:'session',song:previous.song,duration:elapsed,score:scored,scoringVersion:previous.mode==='microphone'?'duration-coverage-v1':'listening-v1',inputRoute:previous.mode,rangeTicks:{start:previous.range.startTick,end:previous.range.endTick},metrics:{pitchCoverage:result?.pitchCoverage??null,validInputFraction:result?.validInputFraction??null}});const live=$('#practice-live');if(live)live.textContent=previous.mode==='microphone'?(valid?`本段音高覆盖 ${scored}% · 有效输入 ${(result.validInputFraction*100).toFixed(0)}% · 参考结果`:'未取得足够可靠的单音输入，本次不生成成绩。'):saved?'示范聆听已记录。继续练一句。':'聆听结束，记录未保存。';}
  async function startPractice(mode){audioPending++;try{return await startPracticeRun(mode);}finally{audioPending--;queueMicrotask(maybeBeginnerGuide);}}
  async function startPracticeRun(mode){const finished=finishPractice(),generation=runId;await finished;if(generation!==runId||page!=='practice')return;tuner=false;metro=false;chord=null;const {range,plan}=rangeModel();if(!plan.length)throw Error('当前段落没有音符，请调整 A–B 小节。');const duration=plan.at(-1).end;if(mode==='microphone'){const live=$('#practice-live');if(live)live.textContent='等待麦克风权限…';await engine.startTuner((hz,meta)=>{if(!run||run.id!==generation)return;const elapsed=(performance.now()-run.started)/1000;SVScoreModel.observeCoverage(run.coverage,{frequency:hz,valid:meta.valid,confidence:meta.confidence},run.lastSample,elapsed);run.lastSample=elapsed;const note=SVPitch.freqToNote(hz,prefs.a4);const el=$('#practice-live');if(el)el.textContent=note?`正在跟奏 · ${note.name} · ${note.cents>0?'+':''}${note.cents} 音分`:'正在跟奏 · 等待可靠的单音输入';});if(generation!==runId||page!=='practice'){engine.stopTuner();return;}}
    run={id:generation,mode,song:song().id,range,duration:prefs.repeat&&mode==='synth'?3600:duration,started:mode==='microphone'?performance.now():null,lastSample:0,coverage:mode==='microphone'?SVScoreModel.createCoverage(plan):null,timer:null};
    if(mode==='synth'){engine.setPreset(prefs.preset);engine.setEffects(prefs.effects);let status;try{status=await engine.play(plan,{loop:prefs.repeat,onPosition:updatePractice,onEnd:result=>{if(result?.error){run=null;runId++;notify(result.error.message);return;}finishPractice().catch(e=>notify(e.message));}});}catch(error){if(run?.id===generation)run=null;engine.stop();throw error;}if(status?.started===false||generation!==runId){if(run?.id===generation)run=null;return;}if(run?.id===generation)run.started=performance.now();const el=$('#practice-live');if(el)el.textContent=`正在示范聆听 · ${prefs.from}–${prefs.to||range.score.barCount} 小节 · ${prefs.repeat?'循环':'单次'}`;}else{run.timer=setInterval(()=>{if(!run||run.id!==generation)return;const elapsed=(performance.now()-run.started)/1000,i=plan.find(n=>elapsed>=n.start&&elapsed<n.end)?.i??-1;updatePractice(i,elapsed,duration);if(elapsed>=duration)finishPractice().catch(e=>notify(e.message));},40);}}
  async function videoCapture(){return videoManager.start({preview:$('#camera-preview')});}
  async function startRecord(kind,trackIndex){if(capture||capturePending||saving){notify('请先停止当前录制。');return;}capturePending=true;const generation=++captureGeneration;render();let recorder;try{await finishPractice();if(generation!==captureGeneration||page!=='studio')return;recorder=kind==='video'?await videoCapture():await engine.startCapture(prefs.source,kind==='loop'?{maxDurationMs:120000}:{});if(generation!==captureGeneration||page!=='studio'){await Promise.allSettled([recorder.stop()]);return;}capture={recorder,kind,trackIndex,started:performance.now(),id:crypto.randomUUID()};recorder.finished?.then(()=>{if(capture?.recorder===recorder&&!saving)stopRecord().catch(e=>notify(e.message));}).catch(()=>{if(capture?.recorder===recorder&&!saving)stopRecord().catch(e=>notify(e.message));});if(prefs.source==='synth'&&kind!=='video'){engine.setPreset(prefs.preset);engine.setEffects(prefs.effects);await engine.play(rangeModel().plan,{loop:kind==='loop'});}recordTimer=setInterval(()=>{const status=$('#record-status'),time=$('#studio-time');if(capture){const elapsed=seconds((performance.now()-capture.started)/1000);if(status)status.textContent=`● 正在录制 ${elapsed} · ${capture.kind==='video'?'视频':prefs.source==='synth'?'浏览器合成':'真实麦克风'}，点击停止保存。`;if(time)time.textContent=elapsed;}},200);}catch(error){if(recorder)await Promise.allSettled([recorder.stop()]);capture=null;clearInterval(recordTimer);engine.stop();throw error;}finally{capturePending=false;if(page==='studio')render();}}
  async function stopRecord(){captureGeneration++;if(!capture){videoManager.cancel();if(capturePending)notify('已取消等待中的录制请求。');return;}const current=capture;capture=null;clearInterval(recordTimer);saving=true;try{const completed=await current.recorder.stop();engine.stop();const row={...completed,id:current.id,kind:current.kind,completed:true,at:new Date().toISOString(),name:`${current.kind==='loop'?T('循环轨')+' '+(current.trackIndex+1):current.kind==='video'?T('视频'):T('录音')} · ${title(song())}`,trackIndex:current.trackIndex};const saved=await SVMediaStore.put(row);await refreshMedia();notify(saved.persisted?'已保存到当前浏览器，请下载备份。':'浏览器未能持久保存；目前仅在内存，请立即下载。');}finally{saving=false;if(page==='studio')render();}}
  async function deleteMedia(id){if(capture||capturePending||saving)throw Error('请先停止并完成当前录制。');engine.stopLoops();loopsPlaying=false;const result=await SVMediaStore.delete(id);if(!result.committed&&result.mode!=='memory')throw Error('媒体删除尚未确认。');await refreshMedia();render();notify(result.committed?'浏览器媒体已删除。':'当前内存媒体已移除；历史持久媒体删除未确认。');}
  const extension=blob=>blob.type.includes('mp4')?'mp4':blob.type.includes('ogg')?'ogg':blob.type.includes('wav')?'wav':'webm';
  function confirmDialog(titleText,copy,act,id){modal(`<h2>${E(titleText)}</h2><p>${E(copy)}</p>${button('确认删除',act,'trash-2','danger',`data-id="${E(id||'')}"`)}`);}
  const closeModal=()=>{$('#modal').close();};
  const actions={
    'skip-startup'(){completeStartup();},
    async 'tutorial-restart'(){if(capture||capturePending||saving)throw Error('请先停止并保存录制，再切换模式或查看教学。');await finishPractice();engine.stop();closeModal();showTutorial(true);},
    async tutorial(){if(capture||capturePending||saving)throw Error('请先停止并保存录制，再切换模式或查看教学。');await finishPractice();engine.stop();tuner=false;metro=false;chord=null;closeModal();showTutorial();},
    async 'set-mode'(el){if(capture||capturePending||saving)throw Error('请先停止并保存录制，再切换模式或查看教学。');const mode=el.dataset.mode;if(!['full','offline'].includes(mode))return;await finishPractice();engine.stopTuner();tuner=false;metro=false;chord=null;prefs.appMode=mode;const saved=persist();window.SVCommunity?.connect(communityContext())?.catch(()=>{});render();notify(!saved?'浏览器暂不允许保存模式与教学设置。':mode==='offline'?'离线模式已启用。':'当前模式已启用。');if(mode==='offline')await prepareOffline();if(!saved)notify('浏览器暂不允许保存模式与教学设置。');},
    'prepare-offline':()=>prepareOffline(true),
    async 'country-settings'(){if(capture||capturePending||saving)throw Error('请先停止并保存录制，再更改国家或语言。');await finishPractice();engine.stop();tuner=false;metro=false;chord=null;closeModal();showWelcome(false);},
    'choose-country'(el){if(!Object.hasOwn(marketLanguages,el.dataset.country))return;countryDraft=el.dataset.country;languageDraft=marketLanguages[countryDraft];renderWelcome();},
    'commit-country'(){applyCountrySelection();},
    'cancel-country'(){dismissWelcome();render();},
    async 'replay-startup'(){if(capture||capturePending||saving)throw Error('请先停止并保存录制，再更改国家或语言。');await finishPractice();engine.stop();tuner=false;metro=false;chord=null;closeModal();render();showStartup(false);},
    menu(){modal(`<span class="eyebrow">YOUR MUSIC, YOUR WAY</span><h2>我的琴房</h2><div class="menu-grid">${nav.map(n=>`<button class="tool-tile" data-go="${n[0]}"><span class="tile-icon">${icon(n[6])}</span><strong>${E(nameOf(n[0]))}</strong></button>`).join('')}</div>`);},
    theme(){prefs.theme=prefs.theme==='dark'?'light':'dark';persist();render();},
    'library-scope'(el){if(!['all','regional','global'].includes(el.dataset.id))return;prefs.libraryScope=el.dataset.id;persist();render();},
    'song-source'(el){const selected=svState.songs.find(s=>s.id===el.dataset.id);if(selected&&sourceURL(selected.source?.url))sourceDialog(selected);},
    'choose-song'(el){const selected=svState.songs.find(s=>s.id===el.dataset.id);if(!selected)return;prefs.song=selected.id;prefs.meter=practiceMeter(selected);prefs.from=1;prefs.to=0;persist();location.hash='practice';if(page==='practice')navigate('practice');},
    favorite(el){const id=el.dataset.id;prefs.favorites=prefs.favorites.includes(id)?prefs.favorites.filter(v=>v!==id):[...prefs.favorites,id];persist();if(page==='library'){const results=$('#song-results');results.innerHTML=libraryRows(filteredSongs());icons();}else if(page==='practice'){el.classList.toggle('active',prefs.favorites.includes(id));el.setAttribute('aria-pressed',String(prefs.favorites.includes(id)));}else render();},
    category(el){category=el.dataset.id;render();},'list-view'(){listView=!listView;prefs.libraryView=listView?'list':'grid';persist();render();},
    play:()=>startPractice('synth'),'mic-practice':()=>startPractice('microphone'),stop:()=>finishPractice(),
    async chord(el){if(run?.mode==='microphone')await finishPractice();const next=el.dataset.id;if(chord===next){engine.stopChord();chord=null;}else{const status=await engine.chord(next,$('#chord-style')?.value||'arp',prefs.bpm);if(status.cancelled)return;chord=status.started?next:null;}document.querySelectorAll('[data-action="chord"]').forEach(e=>{e.classList.toggle('active',e.dataset.id===chord);e.setAttribute('aria-pressed',String(e.dataset.id===chord));});},
    preset(el){prefs.preset=el.dataset.id;engine.setPreset(prefs.preset);persist();render();},
    async audition(){engine.stop();engine.setPreset(prefs.preset);engine.setEffects(prefs.effects);const status=await engine.play(rangeModel().plan);if(status.started)notify('正在试听当前音色。');},'stop-audio'(){engine.stop();},
    'save-preset'(){modal(`<h2>保存当前音色</h2><p><span data-i18n-ignore>${E(T(toneNames[prefs.preset][0]))}</span> · 当前效果参数一起保存</p><label>预设名称<input id="preset-name" maxlength="80" value="${E(T(toneNames[prefs.preset][0])+' · '+T('我的版本'))}"></label><label>分组<input id="preset-group" maxlength="60" value=""></label>${button('保存预设','commit-preset','bookmark','primary')}`);},
    async 'commit-preset'(){const name=$('#preset-name').value.trim();if(!name)throw Error('请填写预设名称。');if(await action({type:'preset-save',name,group:$('#preset-group')?.value||'',preset:prefs.preset,effects:{...prefs.effects},inputGain:prefs.inputGain})){closeModal();render();notify('预设已保存到当前手机浏览器。');}},
    'load-preset'(el){const p=svState.presets.find(p=>p.id===el.dataset.id);if(!p)return;prefs.preset=p.preset;prefs.effects={...p.effects};prefs.inputGain=p.inputGain??1;engine.setInputGain(prefs.inputGain);engine.setPreset(prefs.preset);engine.setEffects(prefs.effects);persist();render();notify('已应用到浏览器音色。');},
    'delete-preset'(el){confirmDialog('删除这个音色预设？','只删除当前浏览器中的预设记录。','commit-delete-preset',el.dataset.id);},async 'commit-delete-preset'(el){if(await action({type:'preset-delete',id:el.dataset.id})){closeModal();render();}},
    'export-presets'(){download('SmartVio-音色预设.json',{schemaVersion:1,target:'browser-synthesis',presets:svState.presets||[]});},
    'rename-preset'(el){const p=svState.presets.find(p=>p.id===el.dataset.id);if(!p)return;modal('<h2>'+E(T('修改预设名称和分组'))+'</h2><label>'+E(T('预设名称'))+'<input id="rename-name" maxlength="80" value="'+E(p.name)+'"></label><label>'+E(T('分组'))+'<input id="rename-group" maxlength="60" value="'+E(p.group||'')+'"></label>'+button('保存预设','commit-rename-preset','save','primary','data-id="'+E(p.id)+'"'));},
    async 'commit-rename-preset'(el){const p=svState.presets.find(p=>p.id===el.dataset.id);if(p&&await action({type:'preset-save',...p,name:$('#rename-name').value,group:$('#rename-group').value})){closeModal();render();}},
    async 'connect-ble-midi'(){try{await deviceBridge.connectBleMidi();if(deviceBridge.status().ble.connected)notify('蓝牙 MIDI 已连接；音频监听由系统和琴端管理。');}finally{updateDeviceStatus();}},
    async 'connect-native'(){await deviceBridge.connectNative();updateDeviceStatus();},
    'disconnect-bridge'(){deviceBridge.disconnect();midiStudio.stopExternalCapture?.('disconnected');updateDeviceStatus();},
    async 'capture-ble-midi'(){if(!deviceBridge.status()?.ble?.connected)throw Error('请先连接真实蓝牙 MIDI 设备。');await midiStudio.startExternalCapture?.('Bluetooth MIDI · '+(deviceBridge.status().ble.name||''));},
    'stop-ble-midi'(){midiStudio.stopExternalCapture?.();},
    async 'store-preset-device'(){const result=await deviceBridge.storePreset({schemaVersion:1,name:'App preset',parameters:{volume:prefs.effects.volume,reverb:prefs.effects.reverb}});if(result.persisted!==true)throw Error('设备尚未确认预设持久保存。');notify('设备已确认预设持久保存。');updateDeviceStatus();},
    'record-loop':el=>startRecord('loop',Number(el.dataset.track)),'record-audio':()=>startRecord('recording'),'record-video':()=>startRecord('video'),'stop-record':()=>stopRecord(),
    async 'play-loops'(){if(capture||capturePending||saving)throw Error('请先停止并完成当前录制。');const generation=++loopRequest,status=await engine.playLoops(media.filter(r=>r.kind==='loop'),prefs.levels,prefs.mutes);if(status.cancelled||generation!==loopRequest)return;loopsPlaying=!!status.started;if($('#studio-time'))$('#studio-time').textContent=loopsPlaying?'回放中':'00:00';notify(status.started?(status.alignedDuration?'各轨已按工程长度循环，原始录音保留。':'四轨按各自录制长度循环播放。'):'还没有循环轨，先录一段。');},'stop-loops'(){loopRequest++;engine.stopLoops();loopsPlaying=false;if($('#studio-time'))$('#studio-time').textContent='00:00';},
    'mute-track'(el){const i=Number(el.dataset.track);prefs.mutes[i]=!prefs.mutes[i];engine.setLoopLevels(prefs.levels,prefs.mutes);persist();render();},
    'download-media'(el){const row=media.find(r=>r.id===el.dataset.id);if(row)download(`SmartVio-${row.kind}-${row.id.slice(0,8)}.${extension(row.blob)}`,row.blob);},
    'delete-media'(el){confirmDialog('删除这段媒体？','删除当前浏览器的媒体文件。请先下载需要保留的内容。','commit-delete-media',el.dataset.id);},async 'commit-delete-media'(el){await deleteMedia(el.dataset.id);closeModal();},
    'clear-track'(el){const row=media.find(r=>r.kind==='loop'&&r.trackIndex===Number(el.dataset.track));if(row)confirmDialog('清空这条循环轨？','删除本机媒体后，引用它的工程将显示缺失。','commit-clear-track',String(row.trackIndex));},
    async 'commit-clear-track'(el){if(capture||capturePending||saving)throw Error('请先停止当前录制。');const all=await SVMediaStore.list('loop',{includeShadowed:true});if(SVMediaStore.status().error?.code==='READ_FAILED')throw Error('媒体读取失败，轨道未删除。');engine.stopLoops();for(const row of all.filter(r=>r.trackIndex===Number(el.dataset.id)))await SVMediaStore.delete(row.id);await refreshMedia();closeModal();render();},
    'save-project'(){if(capture||capturePending||saving)throw Error('请先停止并保存录制。');modal(`<h2>保存本机工程</h2><p>保存速度、小节备注与当前四轨引用。音频存于当前浏览器，不会上传云端。</p><label>工程名称<input id="project-name" maxlength="80" value="${E(T('我的旋律')+' · '+date(new Date()))}"></label>${button('保存工程','commit-project','folder-plus','primary')}`);},
    async 'commit-project'(){const name=$('#project-name').value.trim();if(!name)throw Error('请填写工程名称。');if(await action({type:'project-save',name,bpm:prefs.bpm,barCount:prefs.barCount,trackIds:media.filter(r=>r.kind==='loop').map(r=>r.id)})){closeModal();render();notify('工程参数已保存；音频仍在当前浏览器。');}},
    async 'load-project'(el){const p=svState.projects.find(p=>p.id===el.dataset.id);if(!p)return;const all=await SVMediaStore.list('loop',{includeShadowed:true});if(SVMediaStore.status().error?.code==='READ_FAILED')throw Error('本机音频读取失败。');prefs.bpm=p.bpm;prefs.barCount=p.barCount;persist();const missing=p.trackIds.filter(id=>!all.some(r=>r.id===id));modal(`<h2 data-i18n-ignore>${E(p.name)}</h2><p>${p.bpm} BPM · ${p.barCount} 小节 · ${p.trackIds.length} 轨</p>${missing.length?`<div class="note-box warn"><strong>${missing.length} 条媒体缺失</strong><p>文件不在当前浏览器中，可能被清理、覆盖或保存在另一个地址。工程只有引用，没有云端音频。</p></div>`:'<p>所有轨道音频均已在当前浏览器找到。</p>'}${button('播放这个工程','play-project','play','primary',`data-id="${E(p.id)}" ${missing.length?'disabled':''}`)}`);},
    async 'play-project'(el){if(capture||capturePending||saving)throw Error('请先停止并保存录制。');const generation=++loopRequest,navGeneration=navigationId,p=svState.projects.find(p=>p.id===el.dataset.id),all=await SVMediaStore.list('loop',{includeShadowed:true});if(generation!==loopRequest||navGeneration!==navigationId||page!=='studio')return;if(!p||SVMediaStore.status().error?.code==='READ_FAILED')throw Error('工程媒体读取失败。');const rows=p.trackIds.map(id=>all.find(r=>r.id===id));if(rows.some(r=>!r))throw Error('工程缺少媒体。');const status=await engine.playLoops(rows,prefs.levels,prefs.mutes,{alignLength:prefs.alignLoops,bpm:prefs.bpm,meter:prefs.meter,barCount:prefs.barCount});if(status.cancelled||generation!==loopRequest)return;loopsPlaying=!!status.started;if(!status.started){notify('工程没有可播放的音频。');return;}closeModal();if($('#studio-time'))$('#studio-time').textContent='回放中';notify('本机工程正在播放。');},
    'delete-project'(el){confirmDialog('删除这个工程？','删除工程参数与引用；原音频保留在当前浏览器。','commit-delete-project',el.dataset.id);},async 'commit-delete-project'(el){if(await action({type:'project-delete',id:el.dataset.id})){closeModal();render();}},
    async reference(el){prefs.string=el.dataset.id;persist();await engine.reference(SVScoreModel.frequency(prefs.string,prefs.a4,0));document.querySelectorAll('.string-button').forEach(b=>{const selected=b.dataset.id===prefs.string;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});},
    async 'start-tuner'(){audioPending++;try{engine.stop();await engine.startTuner((hz,meta)=>{if(page!=='tuner')return;const note=SVPitch.freqToNote(hz,prefs.a4),feedback=$('#tuner-feedback');$('#tuner-note').textContent=note?.name||'—';$('#tuner-hz').textContent=note?`${hz.toFixed(1)} Hz · ${note.cents>0?'+':''}${note.cents} 音分`:'尚未检测到可靠单音';$('#tuner-needle').style.left=`${note?Math.max(0,Math.min(100,50+note.cents)):50}%`;if(feedback)feedback.textContent=!note?'请慢拉单音，避免环境噪声。':Math.abs(note.cents)<=5?'音准接近基准':note.cents<0?'偏低 · 稍微调紧琴弦':'偏高 · 稍微调松琴弦';});if(page==='tuner'){tuner=true;render();}else engine.stopTuner();}finally{audioPending--;queueMicrotask(maybeBeginnerGuide);}},'stop-tuner'(){engine.stopTuner();tuner=false;render();},
    async 'start-metro'(){const status=await engine.metronome(prefs.bpm,Number(prefs.meter.split('/')[0]),Number(prefs.meter.split('/')[1]));if(status.cancelled)return;metro=!!status.started;render();},'stop-metro'(){engine.stopMetronome();metro=false;render();},'tempo-down':()=>setPreference('bpm',Math.max(30,prefs.bpm-5)),'tempo-up':()=>setPreference('bpm',Math.min(240,prefs.bpm+5)),
    'connection-help'(){modal('<h2>连接电子小提琴</h2><ol class="feature-list"><li>先用琴本身的耳机或有线输出确认发声。</li><li>录音时，在系统和浏览器中选择正确的麦克风 / USB 声卡输入。</li><li>BLE 参数控制需要真实设备服务 UUID、协议与握手；当前版本尚未接入。</li><li>MIDI 端口可以实际枚举，但端口出现不代表琴的音频已经接通。</li></ol><p>固件版本、电量和端到端时延须从真实设备取得，当前不显示模拟值。</p>');},
    async 'detect-midi'(){if(!navigator.requestMIDIAccess)throw Error('当前浏览器不支持 Web MIDI。');const access=await navigator.requestMIDIAccess({sysex:false});midiPorts=[...access.outputs.values(),...access.inputs.values()].map(p=>({name:p.name,type:p.type,state:p.state}));if(page==='device')render();notify(midiPorts.length?`检测到 ${midiPorts.length} 个实际 MIDI 端口。`:'未发现 MIDI 端口。');},
    lesson(el){const lesson=courses.flatMap(c=>c.lessons).find(l=>l[0]===el.dataset.id);if(!lesson)return;modal(`<img class="lesson-photo" src="learning/${({hold:'welcome',open:'tuner',bow:'phrase',finger:'phrase',cross:'phrase',phrase:'listen',tone:'confidence',record:'record',layer:'record'})[lesson[0]]}.jpg" alt="" width="960" height="640"><span class="eyebrow">${E(T('照片入门'))}</span><h2>${E(lesson[1])}</h2><p>${E(lesson[2])}</p><p class="help-text">原创文字指导。没有复制竞品课程视频或教学内容。</p>${goButton('去练一句','practice','play','primary')}`);},
    async 'lesson-toggle'(el){const done=(svState.userPractice?.completedLessons||[]).includes(el.dataset.id);if(await action({type:'lesson-toggle',id:el.dataset.id,done:!done}))render();},
    'post-dialog'(){modal(`<h2>写一条练习笔记</h2><label>今天的收获<textarea id="post-text" rows="5" maxlength="600" placeholder="例如：今天用 60 BPM 练了第二小节，换弦更稳定了。"></textarea></label><p class="help-text">只保存于当前浏览器，不会上网发布或提交真人审核。</p>${button('保存笔记','commit-post','send','primary')}`);},async 'commit-post'(){if(await action({type:'post',text:$('#post-text').value})){closeModal();render();notify('已保存为当前浏览器的私有草稿。');}},async like(el){if(await action({type:'like',id:el.dataset.id}))render();},
    report(el){modal(`<h2>记录这条笔记的反馈</h2><label>原因<textarea id="report-reason" rows="3" maxlength="200"></textarea></label>${button('提交反馈','commit-report','flag','primary',`data-id="${E(el.dataset.id)}"`)}`);},async 'commit-report'(el){if(await action({type:'report',id:el.dataset.id,reason:$('#report-reason').value})){closeModal();notify('反馈已保存在当前浏览器，不会发送给他人。');}},
    'product-info'(el){const p=svState.products.find(p=>p.id===el.dataset.id);modal(`<h2>${E(T(p?.title.zh||'产品方向'))}</h2><p>${E(T(p?.desc.zh||''))}</p><p>概念外观用于产品规划。完整规格、量产状态、价格与上市时间待确认。</p>`);},
    async 'save-goal'(){const dailyGoal=Number($('#daily-goal').value);if(await action({type:'practice-settings',dailyGoal})){render();notify('每日目标已保存。');}},
    'export-data'(){download('SmartVio-浏览器记录.json',{exportedAt:new Date().toISOString(),scope:'mobile-browser-local',sessions:svState.sessions,projects:svState.projects||[],presets:svState.presets||[],userPractice:svState.userPractice,learningPath:learningPath.state(),midi:midiStudio.state(),media:media.map(({blob,...r})=>({...r,bytes:blob.size,mime:blob.type,audioIncluded:false}))});},
    'export-csv'(){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('SmartVio-练习记录.csv','\uFEFF'+[['日期','曲目','方式','时长秒','参考分','评分版本'].map(T),...svState.sessions.map(r=>[r.at,sessionTitle(r),r.inputRoute||r.kind,r.duration,r.score,r.scoringVersion||''])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');},
    'clear-dialog'(){if(capture||capturePending||saving)throw Error('请先停止并保存录制。');confirmDialog('清除当前浏览器数据？','将删除当前浏览器的练习、笔记、工程、预设和媒体库。JSON不含录音文件或私有笔记、反馈，请先分别备份需要保留的内容。','commit-clear');},
    async 'commit-clear'(){if(capture||capturePending||saving)throw Error('当前录制未完成，未执行删除。');engine.stop();const cleared=await SVMediaStore.clear();await refreshMedia();if(!cleared.committed&&cleared.mode!=='memory')throw Error('浏览器媒体删除未确认，浏览器文字记录保留。');const midiClear=midiStudio.clear();if(!midiClear.committed)throw Error('MIDI 本机项目清除未提交，请保留数据并重试。');const pathClear=learningPath.clear();if(!pathClear.committed)throw Error('Learning progress could not be cleared.');if(await action({type:'clear-user'})){prefs.favorites=[];persist();closeModal();render();notify(cleared.committed?'当前浏览器媒体与文字记录已清除。':'浏览器文字记录已清除；媒体持久存储不可用，历史媒体删除未确认。');}else{closeModal();render();notify('媒体已清除，但浏览器文字记录保存失败，请重试。');}}
  };
  async function setPreference(key,value){if(key==='inputGain'){const next=Number(value)/100;engine.setInputGain(next);prefs.inputGain=next;persist();if($('#input-gain-value'))$('#input-gain-value').textContent=Math.round(next*100)+'%';return;}if(key==='alignLoops'){prefs.alignLoops=typeof value==='boolean'?value:$('#align-loops')?.checked===true;persist();return;}if((capture||capturePending||saving)&&['source','bpm','meter','from','to','semitone','lang','region'].includes(key)){notify('请先停止并保存录制，再修改播放或输入设置。');render();return;}if(['bpm','a4','semitone','from','to','meter'].includes(key)){await finishPractice();engine.stop();metro=false;chord=null;}if(['bpm','a4','semitone','from','to','barCount'].includes(key)){value=Number(value);if(!Number.isFinite(value))return;const limits={bpm:[30,240],a4:[400,480],semitone:[-6,6],from:[1,rangeModel().score.barCount],to:[1,rangeModel().score.barCount],barCount:[1,128]};value=Math.round(Math.min(limits[key][1],Math.max(limits[key][0],value)));}if(key==='lang'&&!['zh','en','ja','de'].includes(value))return;if(key==='region'&&!Object.hasOwn(marketLanguages,value))return;prefs[key]=value;if(key==='tutorialAuto'){prefs.tutorialAuto=value===true;if(prefs.tutorialAuto)prefs.tutorialVersion=0;}if(key==='region')prefs.lang=marketLanguages[value];if(key==='lang'||key==='region'){prefs.localeChoiceVersion=1;window.SVLocale?.setLanguage(prefs.lang,prefs.region);}if(key==='from'&&prefs.to&&prefs.to<prefs.from)prefs.to=prefs.from;if(key==='to'&&prefs.to&&prefs.to<prefs.from)prefs.from=prefs.to;if(key==='meter'){prefs.from=1;prefs.to=0;}persist();render();}
  document.addEventListener('click',async event=>{if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();return;}const target=event.target.closest('[data-go],[data-action]');if(!target||target.disabled)return;if(target.dataset.go){closeModal();const id=target.dataset.go;if(location.hash.slice(1)===id)await navigate(id);else location.hash=id;return;}const handler=actions[target.dataset.action];if(!handler)return;try{await handler(target);}catch(error){notify(error.message||'操作没有完成，请重试。');}});
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='welcome-language'){languageDraft=el.value;renderWelcome();return;}if(el.dataset.pref)setPreference(el.dataset.pref,el.type==='checkbox'?el.checked:el.value).catch(e=>notify(e.message));if(el.id==='noise-gate')SVPitch.setGate(Number(el.value)/1000);});
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='song-search'){query=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const results=$('#song-results');if(results){const rows=filteredSongs();results.innerHTML=libraryRows(rows);const subline=$('.library-subline');if(subline)subline.textContent=librarySubline(rows);icons();}},100);}if(el.dataset.effect){prefs.effects[el.dataset.effect]=Number(el.value)/100;engine.setEffects(prefs.effects);persist();const label=$('#effect-'+el.dataset.effect);if(label)label.textContent=el.value+'%';}if(el.dataset.level!==undefined){const i=Number(el.dataset.level);prefs.levels[i]=Number(el.value)/100;engine.setLoopLevels(prefs.levels,prefs.mutes);persist();const label=el.nextElementSibling;if(label)label.textContent=el.value+'%';}});
  window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}navigate(location.hash.slice(1)).catch(e=>notify(e.message));});
  window.addEventListener('pagehide',()=>{clearTimeout(startupTimer);clearInterval(recordTimer);captureGeneration++;runId++;videoManager.dispose();midiStudio.dispose();performanceStudio.dispose();deviceBridge.dispose();cloudCleanup?.dispose?.();engine.dispose().catch(()=>{});for(const url of urls.values())URL.revokeObjectURL(url);});
  window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});

  function syncBrand(){
    const current=brand();
    const hasWordmark=current==='Silvio'||current==='VELLEN';
    document.querySelectorAll('[data-brand-name],#brand-label,#header-brand-label').forEach(el=>{el.innerHTML=brandMarkup(current);el.classList.toggle('has-wordmark',hasWordmark);el.setAttribute('data-i18n-ignore','');});
    document.querySelectorAll('.brand,.mobile-brand,.header-brand-container').forEach(el=>el.classList.toggle('has-wordmark',hasWordmark));
    document.querySelectorAll('[data-brand-mark]').forEach(el=>el.setAttribute('data-i18n-ignore',''));
    document.querySelectorAll('.brand').forEach(el=>el.setAttribute('aria-label',current+' '+T('我的琴房')));
    document.title=current+' · '+T('我的琴房');
    const footerBrand=document.querySelector('.app-footer>span:first-child');if(footerBrand){footerBrand.textContent=current+' · '+T('我的琴房')+' · V16';footerBrand.setAttribute('data-i18n-ignore','');}
    const appTitle=document.querySelector('meta[name="apple-mobile-web-app-title"]');if(appTitle)appTitle.content=current;
    const description=document.querySelector('meta[name="description"]');if(description)description.content=current+' — '+T('练习、调音、音色与录音创作。');const manifest=document.querySelector('link[rel="manifest"]');if(manifest)manifest.href=(prefs.region==='uk'?'manifest-vellen-':'manifest-')+prefs.lang+'.webmanifest';
    document.querySelectorAll('.avatar-button,.profile-title>.avatar,.workspace-account>.avatar').forEach(el=>el.textContent=current==='VELLEN'?'VE':'SL');
  }
  function setBackgroundInert(active){
    const shell=$('.app-shell'),bottom=$('#bottom-nav');if(shell)shell.inert=active;if(bottom)bottom.inert=active;if(active&&lockedOverflow===null){lockedOverflow=document.documentElement.style.overflow;document.documentElement.style.overflow='hidden';}else if(!active&&lockedOverflow!==null){document.documentElement.style.overflow=lockedOverflow;lockedOverflow=null;}
  }
  function showStartup(initial){
    if($('#startup-layer'))return;
    setBackgroundInert(true);
    const layer=document.createElement('div');layer.id='startup-layer';layer.className='startup-layer';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label',T('开机动画'));layer.dataset.initial=String(initial);
    layer.innerHTML=`<div class="startup-card"><div class="startup-art" aria-hidden="true"><svg class="startup-instrument" viewBox="0 0 200 270" focusable="false"><path class="startup-body" d="M88 82C73 75 51 92 58 117C64 134 75 137 68 148C53 164 47 190 57 217C68 245 134 245 145 217C155 190 149 164 134 148C127 137 138 134 144 117C151 92 127 75 112 82L109 20Q100 4 91 20Z"/><path class="startup-detail" d="M92 21Q100 15 108 21M88 166H114M75 123C65 127 80 137 74 147M127 123C137 127 122 137 128 147M89 221H113"/>${[94,98,102,106].map((x,i)=>`<path class="startup-string" style="--string:${i}" d="M${x} 25V220"/>`).join('')}<g class="startup-note note-one"><ellipse cx="34" cy="78" rx="7" ry="5" transform="rotate(-18 34 78)"/><path d="M40 77V48Q51 48 51 58"/></g><g class="startup-note note-two"><ellipse cx="167" cy="136" rx="7" ry="5" transform="rotate(-18 167 136)"/><path d="M173 135V103"/></g><g class="startup-note note-three"><ellipse cx="43" cy="202" rx="5" ry="4" transform="rotate(-18 43 202)"/><path d="M47 201V179"/></g></svg></div><div class="startup-logo" data-i18n-ignore data-brand-name>${brandMarkup(brand())}</div><p class="startup-caption">${E(T('轻触，开启你的音乐'))}</p></div><button type="button" class="skip-startup" data-action="skip-startup">${E(T('跳过动画'))}${icon('chevron-right')}</button>`;
    document.body.append(layer);icons();layer.querySelector('button').focus();
    startupTimer=setTimeout(completeStartup,matchMedia('(prefers-reduced-motion:reduce)').matches?80:2800);
  }
  function completeStartup(){
    const layer=$('#startup-layer');if(!layer)return;clearTimeout(startupTimer);startupTimer=null;layer.remove();
    if(!localeChoiceConfirmed)showWelcome(true);else if(layer.dataset.initial==='true')continueAfterWelcome();else{setBackgroundInert(false);$('#main').focus({preventScroll:true});}
  }
  function showWelcome(required){
    countryDraft=prefs.region;languageDraft=prefs.lang;setBackgroundInert(true);
    let layer=$('#welcome-layer');if(!layer){layer=document.createElement('div');layer.id='welcome-layer';layer.className='welcome-layer';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');document.body.append(layer);}
    layer.dataset.required=String(required);renderWelcome();
  }
  function renderWelcome(){
    const layer=$('#welcome-layer');if(!layer)return;
    const languages=['en','ja','zh','de'],countries=['us','uk','jp','de','cn','fr'];
    const scrollTop=layer.querySelector('.welcome-content')?.scrollTop||0;
    const focused=document.activeElement,focusLanguage=layer.contains(focused)&&languages.includes(focused.dataset?.welcomeLanguage)?focused.dataset.welcomeLanguage:null;
    const local=value=>window.SVLocale?.text(value,languageDraft,countryDraft)||value;
    const localBrand=brandFor(languageDraft,countryDraft);
    const labels={en:'English',ja:'日本語',de:'Deutsch',zh:'中文'};
    const flags={
      us:`<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#fff"/>${Array.from({length:7},(_,i)=>`<rect y="${i*40/13}" width="30" height="${20/13}" fill="#b31942"/>`).join('')}<rect width="12.5" height="10.77" fill="#0a3161"/>${Array.from({length:9},(_,row)=>Array.from({length:row%2?5:6},(_,col)=>`<circle cx="${.9+(row%2?.95:0)+col*1.9}" cy="${.85+row*1.08}" r=".36" fill="#fff"/>`).join('')).join('')}</svg>`,
      uk:'<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#012169"/><path d="M0 0L30 20M30 0L0 20" stroke="#fff" stroke-width="5"/><path d="M0 0L30 20M30 0L0 20" stroke="#c8102e" stroke-width="2"/><path d="M15 0V20M0 10H30" stroke="#fff" stroke-width="7"/><path d="M15 0V20M0 10H30" stroke="#c8102e" stroke-width="4"/></svg>',
      jp:'<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#fff"/><circle cx="15" cy="10" r="5.5" fill="#bc002d"/></svg>',
      de:'<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#ffce00"/><rect width="30" height="13.34" fill="#d00"/><rect width="30" height="6.67" fill="#111"/></svg>',
      cn:`<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#de2910"/><g fill="#ffde00"><polygon points="5,2 5.7,4.1 7.9,4.1 6.1,5.4 6.8,7.4 5,6.1 3.2,7.4 3.9,5.4 2.1,4.1 4.3,4.1"/>${[[9.5,2.5,20],[11,4.5,40],[11,7.5,0],[9.5,9.5,20]].map(([x,y,r])=>`<polygon points="0,-1 .3,-.3 1,-.3 .4,.2 .6,1 0,.5 -.6,1 -.4,.2 -1,-.3 -.3,-.3" transform="translate(${x} ${y}) rotate(${r})"/>`).join('')}</g></svg>`,
      fr:'<svg viewBox="0 0 30 20" focusable="false"><rect width="30" height="20" fill="#ed2939"/><rect width="20" height="20" fill="#fff"/><rect width="10" height="20" fill="#002395"/></svg>'
    };
    layer.lang=languageDraft;layer.setAttribute('aria-label',local('选择你的国家'));
    layer.innerHTML=`<section class="welcome-card"><header class="welcome-header"><div class="welcome-brand" data-i18n-ignore>${localBrand==='Silvio'||localBrand==='VELLEN'?'':icon('audio-lines')}${brandMarkup(localBrand)}</div><div class="welcome-progress" aria-hidden="true"><span>1</span><i></i><span>2</span></div></header><div class="welcome-content"><div class="welcome-section-heading"><span class="welcome-step-no" aria-hidden="true">01</span><h1 class="welcome-title">${E(local('选择你的国家'))}</h1></div><p class="welcome-copy">${E(local('国家决定默认语言，也可以单独更改语言。'))}</p><div class="country-grid">${countries.map(code=>`<button type="button" class="country-option ${countryDraft===code?'selected':''}" data-action="choose-country" data-country="${code}" aria-pressed="${countryDraft===code}"><span class="country-flag" aria-hidden="true">${flags[code]}</span><span class="country-name">${E(local(regions[code]))}</span><span class="country-language" data-i18n-ignore>${labels[marketLanguages[code]]}</span><span class="country-brand" data-i18n-ignore>${brandMarkup(brandFor(marketLanguages[code],code))}</span><span class="country-check" aria-hidden="true">${icon('check')}</span></button>`).join('')}</div><section class="welcome-language"><div class="welcome-section-heading"><span class="welcome-step-no" aria-hidden="true">02</span><span id="welcome-language-label">${E(local('界面语言'))}</span></div><div class="welcome-language-options" role="radiogroup" aria-labelledby="welcome-language-label">${languages.map(lang=>`<button type="button" class="welcome-language-option ${languageDraft===lang?'selected':''}" data-welcome-language="${lang}" role="radio" aria-checked="${languageDraft===lang}" tabindex="${languageDraft===lang?'0':'-1'}"><span data-i18n-ignore>${labels[lang]}</span><span class="language-check" aria-hidden="true">${icon('check')}</span></button>`).join('')}</div><select id="welcome-language" hidden aria-hidden="true" tabindex="-1" aria-label="${E(local('界面语言'))}">${languages.map(lang=>`<option value="${lang}" ${languageDraft===lang?'selected':''} data-i18n-ignore>${labels[lang]}</option>`).join('')}</select></section><p class="welcome-copy welcome-data-note">${icon('shield-check')}<span>${E(local('记录只保存在当前浏览器，不会因为切换国家或语言而清空。'))}</span></p></div><footer class="welcome-actions"><button type="button" class="button primary" data-action="commit-country">${E(local('继续进入琴房'))}${icon('arrow-right')}</button>${layer.dataset.required==='false'?`<button type="button" class="button secondary" data-action="cancel-country">${E(local('取消'))}</button>`:''}</footer></section>`;
    layer.setAttribute('data-i18n-ignore','');icons();layer.querySelector('.welcome-content').scrollTop=scrollTop;
    const chooseLanguage=lang=>{layer.querySelector(`[data-welcome-language="${lang}"]`)?.focus({preventScroll:true});const select=layer.querySelector('#welcome-language');select.value=lang;select.dispatchEvent(new Event('change',{bubbles:true}));};
    for(const el of layer.querySelectorAll('[data-welcome-language]')){
      el.addEventListener('click',()=>chooseLanguage(el.dataset.welcomeLanguage));
      el.addEventListener('keydown',event=>{const keys=['ArrowLeft','ArrowUp','ArrowRight','ArrowDown','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();const current=languages.indexOf(el.dataset.welcomeLanguage),index=event.key==='Home'?0:event.key==='End'?languages.length-1:(current+(['ArrowLeft','ArrowUp'].includes(event.key)?-1:1)+languages.length)%languages.length;chooseLanguage(languages[index]);});
    }
    const focusTarget=focusLanguage?layer.querySelector(`[data-welcome-language="${focusLanguage}"]`):[...layer.querySelectorAll('[data-country]')].find(el=>el.dataset.country===countryDraft);focusTarget?.focus({preventScroll:true});
  }
  function dismissWelcome(){const layer=$('#welcome-layer');if(layer)layer.remove();setBackgroundInert(false);window.SVLocale?.setLanguage(prefs.lang,prefs.region);$('#main').focus({preventScroll:true});}
  function applyCountrySelection(){
    if(capture||capturePending||saving){notify('请先停止并保存录制，再更改国家或语言。');return;}
    if(!Object.hasOwn(marketLanguages,countryDraft)||!['zh','en','ja','de'].includes(languageDraft))return;
    const required=$('#welcome-layer')?.dataset.required==='true';const next={...prefs,region:countryDraft,lang:languageDraft,localeChoiceVersion:1};let saved=true;
    try{localStorage.setItem('sv12-prefs',JSON.stringify(next));}catch{saved=false;}
    Object.assign(prefs,next);prefs.localeChoiceVersion=saved?1:0;localeChoiceConfirmed=true;dismissWelcome();render();if(required)continueAfterWelcome();notify(saved?'已切换国家、语言和品牌。':'不能保存国家选择；本次仅在当前页面使用，请检查浏览器存储权限。');
  }
  document.addEventListener('keydown',event=>{
    const layer=$('#startup-layer')||$('#welcome-layer');if(!layer)return;
    if(event.key==='Escape'){event.preventDefault();if(layer.id==='startup-layer')completeStartup();else if(layer.dataset.required==='false'){dismissWelcome();render();}return;}
    if(event.key==='Tab'){const focusables=[...layer.querySelectorAll('button,select')].filter(el=>!el.disabled&&el.getClientRects().length>0),first=focusables[0],last=focusables.at(-1);if(!first)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
  });

  window.SVCommunity?.subscribe((state,meta)=>{
    guideCloud=state?.viewer?.onboarding||null;guideCloudStatus=meta.status;
    if(['home','library','profile','learn'].includes(page)&&!window.SVTutorial?.isOpen)render();
    maybeBeginnerGuide();void flushGuideProgress();
  });
  function restorePersonalSongSelections(){
    const personal=svState.songs.filter(s=>s.category==='custom'),ids=new Set(personal.map(s=>s.id)),aliases=new Map();
    const acknowledged=new Set(Array.isArray(prefs.personalSongMigrations)?prefs.personalSongMigrations.filter(v=>typeof v==='string'&&v.length<=160):[]);
    for(const s of personal)if(s.legacyCatalogId&&!ids.has(s.legacyCatalogId)&&!aliases.has(s.legacyCatalogId)&&!acknowledged.has(s.legacyCatalogId))aliases.set(s.legacyCatalogId,s.id);
    if(!aliases.size)return;
    const selected=aliases.get(prefs.song)||prefs.song,favorites=[...new Set(prefs.favorites.map(id=>aliases.get(id)||id))];
    for(const from of aliases.keys())acknowledged.add(from);
    prefs.song=selected;prefs.favorites=favorites;prefs.personalSongMigrations=[...acknowledged];persist();
  }
  document.addEventListener('change',async event=>{if(event.target.id!=='preset-import')return;const file=event.target.files?.[0];if(!file)return;try{if(file.size>100000)throw Error('预设文件过大。');const data=JSON.parse(await file.text());if(data.schemaVersion!==1||!Array.isArray(data.presets))throw Error('预设文件格式不正确。');await restorePresets(data.presets);}catch(error){notify(error.message);}});
  async function init(){await connectApi();restorePersonalSongSelections();await refreshMedia();engine.setPreset(prefs.preset);engine.setEffects(prefs.effects);engine.setInputGain(prefs.inputGain);page=views[location.hash.slice(1)]?location.hash.slice(1):'home';render();showStartup(true);window.SVCommunity?.connect(communityContext())?.catch(()=>{});}
  init().catch(error=>{render();notify(error.message);});
})();
